INSERT INTO rpg.phb_creature_template_trait (template_slug, name, description, sort_order) VALUES
  ('aspirante-cavaleiro-da-morte', 'Sentidos', 'Visão no Escuro 36 m. Percepção Passiva 11.', 0),
  ('aspirante-cavaleiro-da-morte', 'Magic Resistance', 'The aspirant has Advantage on saving throws against spells and other magical effects.', 1),
  ('aspirante-cavaleiro-da-morte', 'Marshal Undead', 'Undead creatures of the aspirant’s choice (excluding itself) in a 60-foot Emanation originating from it have Advantage on attack rolls and saving throws. It can’t use this trait if it has the Incapacitated condition.', 2),
  ('boca-delirante', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 10.', 0),
  ('boca-delirante', 'Aberrant Ground', 'The ground in a 10-foot Emanation originating from the mouther is Difficult Terrain.', 1),
  ('boca-delirante', 'Gibbering', 'The mouther babbles incoherently while it doesn’t have the Incapacitated condition. Wisdom Saving Throw: DC 10, any creature that starts its turn within 20 feet of the mouther while it is babbling. Failure: The target rolls 1d8 to determine what it does during the current turn:', 2),
  ('bruxa-verde', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 14.', 0),
  ('bruxa-verde', 'Amphibious', 'The hag can breathe air and water.', 1),
  ('bruxa-verde', 'Coven Magic', 'While within 30 feet of at least two hag allies, the hag can cast one of the following spells, requiring no Material components, using the spell’s normal casting time, and using Intelligence as the spellcasting ability (spell save DC 11): Augury, Find Familiar, Identify, Locate Object, Scrying, or Unseen Servant. The hag must finish a Long Rest before using this trait to cast that spell again.', 2),
  ('bruxa-verde', 'Mimicry', 'The hag can mimic animal sounds and humanoid voices. A creature that hears the sounds can tell they are imitations only with a successful DC 14 Wisdom (Insight) check.', 3),
  ('cambiao', 'Sentidos', 'Visão no Escuro 36 m. Percepção Passiva 14.', 0),
  ('cao-da-morte', 'Sentidos', 'Visão no Escuro 36 m. Percepção Passiva 15.', 0),
  ('cao-infernal', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 15.', 0),
  ('cao-infernal', 'Pack Tactics', 'The hound has Advantage on an attack roll against a creature if at least one of the hound’s allies is within 5 feet of the creature and the ally doesn’t have the Incapacitated condition.', 1),
  ('capitao-da-guarda', 'Sentidos', 'Percepção Passiva 14.', 0),
  ('cataclismo-elemental', 'Sentidos', 'Visão Verdadeira 45 m. Percepção Passiva 12.', 0),
  ('cataclismo-elemental', 'Earth Glide', 'The cataclysm can burrow through nonmagical, unworked earth and stone. While doing so, the cataclysm doesn’t disturb the material it moves through.', 1),
  ('cataclismo-elemental', 'Legendary Resistance (4/Day)', 'If the cataclysm fails a saving throw, it can choose to succeed instead.', 2),
  ('cataclismo-elemental', 'Siege Monster', 'The cataclysm deals double damage to objects and structures.', 3),
  ('cavaleiro', 'Sentidos', 'Percepção Passiva 10.', 0),
  ('cavaleiro-da-morte', 'Sentidos', 'Visão no Escuro 36 m. Percepção Passiva 13.', 0),
  ('cavaleiro-da-morte', 'Legendary Resistance (3/Day)', 'If the death knight fails a saving throw, it can choose to succeed instead.', 1),
  ('cavaleiro-da-morte', 'Magic Resistance', 'The death knight has Advantage on saving throws against spells and other magical effects.', 2),
  ('cavaleiro-da-morte', 'Marshal Undead', 'Undead creatures of the death knight’s choice (excluding itself) in a 60-foot Emanation originating from it have Advantage on attack rolls and saving throws. It can’t use this trait if it has the Incapacitated condition.', 3),
  ('cavaleiro-da-morte', 'Undead Restoration', 'If the death knight is destroyed before it atones for its evil, it gains a new body in 1d10 days, reviving with all its Hit Points. The new body appears in a location significant to the death knight.', 4),
  ('cavaleiro-em-missao', 'Sentidos', 'Percepção Passiva 15.', 0),
  ('cavaleiro-em-missao', 'Aura of Bravery', 'Creatures of the knight’s choice in a 30-foot Emanation originating from it have Immunity to the Charmed and Frightened conditions while there.', 1),
  ('centauro-guardiao', 'Sentidos', 'Percepção Passiva 17.', 0),
  ('centauro-soldado', 'Sentidos', 'Percepção Passiva 13.', 0),
  ('chacal-homem', 'Sentidos', 'Visão no Escuro 27 m. Percepção Passiva 14.', 0),
  ('chacal-homem', 'Pack Tactics', 'The jackalwere has Advantage on an attack roll against a creature if at least one of the jackalwere’s allies is within 5 feet of the creature and the ally doesn’t have the Incapacitated condition.', 1),
  ('chasme', 'Sentidos', 'Visão às Cegas 3 m, Visão no Escuro 36 m. Percepção Passiva 15.', 0),
  ('chasme', 'Demonic Restoration', 'If the chasme dies outside the Abyss, its body dissolves into ichor, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Abyss.', 1),
  ('chasme', 'Magic Resistance', 'The chasme has Advantage on saving throws against spells and other magical effects.', 2),
  ('chasme', 'Spider Climb', 'The chasme can climb difficult surfaces, including along ceilings, without needing to make an ability check.', 3),
  ('chuul', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 14.', 0),
  ('chuul', 'Amphibious', 'The chuul can breathe air and water.', 1),
  ('chuul', 'Sense Magic', 'The chuul senses magic within 120 feet of itself. This trait otherwise works like the Detect Magic spell but isn’t itself magical.', 2),
  ('ciclope-oraculo', 'Sentidos', 'Visão Verdadeira 9 m. Percepção Passiva 22.', 0),
  ('ciclope-sentinela', 'Sentidos', 'Percepção Passiva 8.', 0),
  ('cocatrice', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 11.', 0),
  ('cocatrice-regente', 'Sentidos', 'Visão no Escuro 36 m. Percepção Passiva 13.', 0),
  ('cocatrice-regente', 'Flyby', 'The cockatrice doesn’t provoke an Opportunity Attack when it flies out of an enemy’s reach.', 1),
  ('colosso', 'Sentidos', 'Visão Verdadeira 90 m. Percepção Passiva 10.', 0),
  ('colosso', 'Immutable Form', 'The colossus can’t shape-shift.', 1),
  ('colosso', 'Legendary Resistance (4/Day)', 'If the colossus fails a saving throw, it can choose to succeed instead.', 2),
  ('colosso', 'Magic Resistance', 'The colossus has Advantage on saving throws against spells and other magical effects.', 3),
  ('colosso', 'Siege Monster', 'The colossus deals double damage to objects and structures.', 4),
  ('couatl', 'Sentidos', 'Visão Verdadeira 36 m. Percepção Passiva 15.', 0),
  ('couatl', 'Shielded Mind', 'The couatl’s thoughts can’t be read by any means, and other creatures can communicate with it telepathically only if it allows them.', 1),
  ('cranio-flamejante', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 12.', 0),
  ('cranio-flamejante', 'Illumination', 'The flameskull sheds Bright Light in a 15-foot radius and Dim Light for an additional 15 feet.', 1),
  ('cranio-flamejante', 'Magic Resistance', 'The flameskull has Advantage on saving throws against spells and other magical effects.', 2),
  ('cranio-flamejante', 'Undead Restoration', 'If the flameskull is destroyed, it regains all its Hit Points in 1 hour unless Holy Water is sprinkled on its remains or the Dispel Evil and Good spell is cast on them.', 3),
  ('cubo-gelatinoso', 'Sentidos', 'Visão às Cegas 18 m. Percepção Passiva 8.', 0),
  ('cubo-gelatinoso', 'Ooze Cube', 'The cube fills its entire space and is transparent. Other creatures can enter that space, but a creature that does so is subjected to the cube’s Engulf and has Disadvantage on the saving throw.', 1),
  ('cubo-gelatinoso', 'Transparent', 'Even when the cube is in plain sight, a creature must succeed on a DC 15 Wisdom (Perception) check to notice the cube if the creature hasn’t witnessed the cube move or otherwise act.', 2),
  ('cultista', 'Sentidos', 'Percepção Passiva 10.', 0),
  ('cultista-aberrante', 'Sentidos', 'Visão no Escuro 27 m. Percepção Passiva 17.', 0),
  ('cultista-da-morte', 'Sentidos', 'Percepção Passiva 16.', 0),
  ('cultista-diabolico', 'Sentidos', 'Visão no Escuro 27 m (unimpeded by magical Darkness). Percepção Passiva 17.', 0),
  ('cultista-elemental', 'Sentidos', 'Percepção Passiva 17.', 0),
  ('cultista-fanatico', 'Sentidos', 'Percepção Passiva 12.', 0),
  ('cultista-hierofante', 'Sentidos', 'Percepção Passiva 17.', 0),
  ('dao', 'Sentidos', 'Visão no Escuro 36 m. Percepção Passiva 11.', 0),
  ('dao', 'Earth Glide', 'The dao can burrow through nonmagical, unworked earth and stone. While doing so, the dao doesn’t disturb the material it moves through.', 1),
  ('dao', 'Elemental Restoration', 'If the dao dies outside the Elemental Plane of Earth, its body dissolves into dirt, and it gains a new body in 1d4 days, reviving with all its Hit Points somewhere on the Plane of Earth.', 2),
  ('dao', 'Magic Resistance', 'The dao has Advantage on saving throws against spells and other magical effects.', 3),
  ('dao', 'Wishes', 'The dao has a 30 percent chance of knowing the Wish spell. If the dao knows it, the dao can cast it only on behalf of a non-genie creature who communicates a wish in a way the dao can understand. If the dao casts the spell for the creature, the dao suffers none of the spell’s stress. Once the dao has cast it three times, the dao can’t do so again for 365 days.', 4),
  ('deva', 'Sentidos', 'Visão no Escuro 36 m. Percepção Passiva 19.', 0),
  ('deva', 'Exalted Restoration', 'If the deva dies outside Mount Celestia, its body disappears, and it gains a new body instantly, reviving with all its Hit Points somewhere in Mount Celestia.', 1),
  ('deva', 'Magic Resistance', 'The deva has Advantage on saving throws against spells and other magical effects.', 2),
  ('devorador-de-intelecto', 'Sentidos', 'Visão às Cegas 18 m. Percepção Passiva 12.', 0),
  ('devorador-de-intelecto', 'Detect Intelligence', 'The intellect devourer magically senses the location of any creature within 300 feet of itself that has an Intelligence score of 3 or higher, regardless of interposing barriers.', 1),
  ('diabo-acorrentado', 'Sentidos', 'Visão no Escuro 36 m (unimpeded by magical Darkness). Percepção Passiva 11.', 0),
  ('diabo-acorrentado', 'Diabolical Restoration', 'If the devil dies outside the Nine Hells, its body disappears in sulfurous smoke, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Nine Hells.', 1),
  ('diabo-acorrentado', 'Magic Resistance', 'The devil has Advantage on saving throws against spells and other magical effects.', 2),
  ('diabo-cornudo', 'Sentidos', 'Visão no Escuro 45 m (unimpeded by magical Darkness). Percepção Passiva 13.', 0),
  ('diabo-cornudo', 'Diabolical Restoration', 'If the devil dies outside the Nine Hells, its body disappears in sulfurous smoke, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Nine Hells.', 1),
  ('diabo-cornudo', 'Magic Resistance', 'The devil has Advantage on saving throws against spells and other magical effects.', 2),
  ('diabo-do-gelo', 'Sentidos', 'Visão às Cegas 36 m. Percepção Passiva 17.', 0),
  ('diabo-do-gelo', 'Diabolical Restoration', 'If the devil dies outside the Nine Hells, its body disappears in sulfurous smoke, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Nine Hells.', 1),
  ('diabo-do-gelo', 'Magic Resistance', 'The devil has Advantage on saving throws against spells and other magical effects.', 2),
  ('diabrete', 'Sentidos', 'Visão no Escuro 36 m (unimpeded by magical Darkness). Percepção Passiva 11.', 0),
  ('diabrete', 'Magic Resistance', 'The imp has Advantage on saving throws against spells and other magical effects.', 1),
  ('djinn', 'Sentidos', 'Visão no Escuro 36 m. Percepção Passiva 13.', 0),
  ('djinn', 'Elemental Restoration', 'If the djinni dies outside the Elemental Plane of Air, its body dissolves into mist, and it gains a new body in 1d4 days, reviving with all its Hit Points somewhere on the Plane of Air.', 1),
  ('djinn', 'Magic Resistance', 'The djinni has Advantage on saving throws against spells and other magical effects.', 2),
  ('djinn', 'Wishes', 'The djinni has a 30 percent chance of knowing the Wish spell. If the djinni knows it, the djinni can cast it only on behalf of a non-genie creature who communicates a wish in a way the djinni can understand. If the djinni casts the spell for the creature, the djinni suffers none of the spell’s stress. Once the djinni has cast it three times, the djinni can’t do so again for 365 days.', 3),
  ('doppelganger', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 11.', 0),
  ('dracolich', 'Sentidos', 'Visão às Cegas 18 m, Visão no Escuro 36 m. Percepção Passiva 24.', 0),
  ('dracolich', 'Legendary Resistance (3/Day, or 4/Day in Lair)', 'If the dracolich fails a saving throw, it can choose to succeed instead.', 1),
  ('dracolich', 'Life Suppression', 'Creatures within 60 feet of the dracolich can’t regain Hit Points.', 2),
  ('dracolich', 'Magic Resistance', 'The dracolich has Advantage on saving throws against spells and other magical effects.', 3),
  ('dracolich', 'Soul Gem', 'The dracolich has a magical gem. If the dracolich is destroyed while the gem is on the same plane of existence as it, the dracolich gains a new body in 1d20 days, regaining all its Hit Points and appearing within 5 feet of the gem.', 4),
  ('dragao-de-cobre-adulto', 'Sentidos', 'Visão às Cegas 18 m, Visão no Escuro 36 m. Percepção Passiva 22.', 0),
  ('dragao-de-cobre-adulto', 'Legendary Resistance (3/Day, or 4/Day in Lair)', 'If the dragon fails a saving throw, it can choose to succeed instead.', 1),
