  ('dragonete-dragao-de-cobre', 'Sentidos', 'Visão às Cegas 3 m, Visão no Escuro 18 m. Percepção Passiva 14.', 0),
  ('dragonete-dragao-dourado', 'Sentidos', 'Visão às Cegas 3 m, Visão no Escuro 18 m. Percepção Passiva 14.', 0),
