  ('dretch', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 9.', 0),
  ('driade', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 14.', 0),
  ('driade', 'Magic Resistance', 'The dryad has Advantage on saving throws against spells and other magical effects.', 1),
  ('driade', 'Speak with Beasts and Plants', 'The dryad can communicate with Beasts and Plants as if they shared a language.', 2),
  ('drider', 'Sentidos', 'Visão no Escuro 36 m. Percepção Passiva 16.', 0),
  ('drider', 'Spider Climb', 'The drider can climb difficult surfaces, including along ceilings, without needing to make an ability check.', 1),
  ('drider', 'Sunlight Sensitivity', 'While in sunlight, the drider has Disadvantage on ability checks and attack rolls.', 2),
  ('drider', 'Web Walker', 'The drider ignores movement restrictions caused by webs, and the drider knows the location of any other creature in contact with the same web.', 3),
  ('druida', 'Sentidos', 'Percepção Passiva 15.', 0),
  ('efrite', 'Sentidos', 'Visão no Escuro 36 m. Percepção Passiva 12.', 0),
  ('efrite', 'Elemental Restoration', 'If the efreeti dies outside the Elemental Plane of Fire, its body dissolves into ash, and it gains a new body in 1d4 days, reviving with all its Hit Points somewhere on the Plane of Fire.', 1),
  ('efrite', 'Magic Resistance', 'The efreeti has Advantage on saving throws against spells and other magical effects.', 2),
  ('efrite', 'Wishes', 'The efreeti has a 30 percent chance of knowing the Wish spell. If the efreeti knows it, the efreeti can cast it only on behalf of a non-genie creature who communicates a wish in a way the efreeti can understand. If the efreeti casts the spell for the creature, the efreeti suffers none of the spell’s stress. Once the efreeti has cast it three times, the efreeti can’t do so again for 365 days.', 3),
  ('elemental-da-terra', 'Sentidos', 'Visão no Escuro 18 m, Sentido Sísmico 18 m. Percepção Passiva 10.', 0),
  ('elemental-da-terra', 'Earth Glide', 'The elemental can burrow through nonmagical, unworked earth and stone. While doing so, the elemental doesn’t disturb the material it moves through.', 1),
  ('elemental-da-terra', 'Siege Monster', 'The elemental deals double damage to objects and structures.', 2),
  ('elemental-do-fogo', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 10.', 0),
  ('elemental-do-fogo', 'Fire Aura', 'At the end of each of the elemental’s turns, each creature in a 10-foot Emanation originating from the elemental takes 5 (1d10) Fire damage. Creatures and flammable objects in the Emanation start burning.', 1),
  ('elemental-do-fogo', 'Fire Form', 'The elemental can move through a space as narrow as 1 inch without expending extra movement to do so, and it can enter a creature’s space and stop there. The first time it enters a creature’s space on a turn, that creature takes 5 (1d10) Fire damage.', 2),
  ('elemental-do-fogo', 'Illumination', 'The elemental sheds Bright Light in a 30-foot radius and Dim Light for an additional 30 feet.', 3),
  ('elemental-do-fogo', 'Water Susceptibility', 'The elemental takes 3 (1d6) Cold damage for every 5 feet the elemental moves in water or for every gallon of water splashed on it.', 4),
  ('empirico', 'Sentidos', 'Visão Verdadeira 36 m. Percepção Passiva 23.', 0),
  ('empirico', 'Legendary Resistance (4/Day)', 'If the empyrean fails a saving throw, it can choose to succeed instead.', 1),
  ('empirico', 'Magic Resistance', 'The empyrean has Advantage on saving throws against spells and other magical effects.', 2),
  ('empirico-iota', 'Sentidos', 'Visão Verdadeira 9 m. Percepção Passiva 15.', 0),
  ('empirico-iota', 'Incorporeal Movement', 'The empyrean can move through other creatures and objects as if they were Difficult Terrain. It takes 5 (1d10) Force damage if it ends its turn inside an object.', 1),
  ('empirico-iota', 'Magic Resistance', 'The empyrean has Advantage on saving throws against spells and other magical effects.', 2),
  ('enxame-de-dretches', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 9.', 0),
  ('enxame-de-dretches', 'Fetid Aura', 'Constitution Saving Throw: DC 12, any creature that starts its turn in a 10-foot Emanation originating from the swarm. Failure: The target has the Poisoned condition until the start of its next turn. While Poisoned, the target can take either an action or a Bonus Action on its turn, not both, and it can’t take Reactions.', 1),
  ('enxame-de-dretches', 'Swarm', 'The swarm can occupy another creature’s space and vice versa, and the swarm can move through any opening large enough for a Small creature. The swarm can’t regain Hit Points or gain Temporary Hit Points.', 2),
  ('enxame-de-garras-rastejantes', 'Sentidos', 'Visão às Cegas 9 m. Percepção Passiva 10.', 0),
