  ('enxame-de-lemures', 'Hellish Restoration', 'If the swarm dies in the Nine Hells, it revives with all its Hit Points in 1d10 days unless it is killed by a creature under the effects of a Bless spell or its remains are sprinkled with Holy Water.', 1),
