  ('erinia', 'Sentidos', 'Visão Verdadeira 36 m. Percepção Passiva 16.', 0),
  ('erinia', 'Diabolical Restoration', 'If the erinyes dies outside the Nine Hells, its body disappears in sulfurous smoke, and it gains a new body instantly, reviving with all its Hit Points somewhere in the Nine Hells.', 1),
  ('erinia', 'Magic Resistance', 'The erinyes has Advantage on saving throws against spells and other magical effects.', 2),
  ('erinia', 'Magic Rope', 'The erinyes has a magic rope. While bearing it, the erinyes can use the Entangling Rope action. The rope has AC 20, HP 90, and Immunity to Poison and Psychic damage. The rope turns to dust if reduced to 0 Hit Points, if it is 5+ feet away from the erinyes for 1 hour or more, or if the erinyes dies. If the rope is damaged or destroyed, the erinyes can fully restore it when finishing a Short or Long Rest.', 3),
  ('ettercap', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 13.', 0),
  ('ettercap', 'Spider Climb', 'The ettercap can climb difficult surfaces, including along ceilings, without needing to make an ability check.', 1),
  ('ettercap', 'Web Walker', 'The ettercap ignores movement restrictions caused by webs, and the ettercap knows the location of any other creature in contact with the same web.', 2),
