  ('fantasma', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 11.', 0),
  ('fantasma', 'Ethereal Sight', 'The ghost can see 60 feet into the Ethereal Plane when it is on the Material Plane.', 1),
  ('fantasma', 'Incorporeal Movement', 'The ghost can move through other creatures and objects as if they were Difficult Terrain. It takes 5 (1d10) Force damage if it ends its turn inside an object.', 2),
  ('fera-deslocadora', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 11.', 0),
  ('fera-deslocadora', 'Avoidance', 'If the displacer beast is subjected to an effect that allows it to make a saving throw to take only half damage, it instead takes no damage if it succeeds on the save and half damage if it fails. It can’t use this trait if it has the Incapacitated condition.', 1),
  ('fera-deslocadora', 'Displacement', 'Attack rolls against the displacer beast have Disadvantage, since it projects an illusion that makes it appear to be near its actual location. This trait is suppressed while the displacer beast has the Incapacitated condition.', 2),
  ('flumph', 'Sentidos', 'Visão no Escuro 18 m. Percepção Passiva 12.', 0),
  ('flumph', 'Advanced Telepathy', 'The flumph perceives the content of any telepathic communication within 60 feet of it.', 1),
  ('flumph', 'Prone Deficiency', 'If the flumph receives the Prone condition, roll a die. On an odd number, it has the Incapacitated condition. At the end of each of its turns, the flumph makes a DC 10 Dexterity saving throw, ending the Incapacitated condition on a success.', 2),
  ('flumph', 'Telepathic Shroud', 'The flumph’s thoughts can’t be read by any means, and magic can’t detect its location or observe it remotely.', 3),
