  ('fungo-esporo-de-gas', 'Death Burst', 'The gas spore bursts when it dies. Constitution Saving Throw: DC 10, each creature in a 20-foot Emanation originating from the gas spore. Failure: The target takes 10 (3d6) Poison damage and has the Poisoned condition for 1d12 hours. Unless the Poisoned condition is removed, the target dies at the end of that time and sprouts 2d4 Tiny Gas Spore Fungi (each with 1 Hit Point). After 2d6 days, they become Large and have 13 Hit Points.', 1),
