INSERT INTO rpg.phb_creature_template_action (
  template_slug, name, action_bucket, attack_bonus, damage_expression, description, sort_order
) VALUES
  ('aspirante-cavaleiro-da-morte', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The aspirant makes three Dread Blade attacks.', 1),
  ('aspirante-cavaleiro-da-morte', 'Dread Blade', 'action'::rpg.actor_action_bucket, 9, '14', 'Melee Attack Roll: +9, reach 5 ft. Hit: 14 (2d8 + 5) Slashing damage plus 10 (3d6) Necrotic damage.', 2),
  ('aspirante-cavaleiro-da-morte', 'Hellfire Orb (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 15, each creature in a 20-foot-radius Sphere centered on a point the aspirant can see within 120 feet of itself. Failure: 21 (6d6) Fire damage plus 21 (6d6) Necrotic damage. Success: Half damage.', 3),
  ('aspirante-cavaleiro-da-morte', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The aspirant casts one of the following spells, using Charisma as the spellcasting ability (spell save DC 15):', 4),
  ('aspirante-cavaleiro-da-morte', 'Parry', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The aspirant is hit by a melee attack roll while holding a weapon. Response: The aspirant adds 4 to its AC against that attack, possibly causing it to miss.', 5),
  ('boca-delirante', 'Bite', 'action'::rpg.actor_action_bucket, 2, '7', 'Melee Attack Roll: +2, reach 5 ft. Hit: 7 (2d6) Piercing damage. If the target is a Medium or smaller creature, it has the Prone condition. The target dies if it is reduced to 0 Hit Points by this attack. Its body is then absorbed into the mouther, leaving only equipment behind.', 1),
  ('boca-delirante', 'Blinding Spittle (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 10, each creature in a 10-foot-radius Sphere centered on a point within 30 feet. Failure: 7 (2d6) Radiant damage, and the target has the Blinded condition until the end of the mouther’s next turn.', 2),
  ('bruxa-verde', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The hag makes two Claw attacks.', 1),
  ('bruxa-verde', 'Claw', 'action'::rpg.actor_action_bucket, 6, '8', 'Melee Attack Roll: +6, reach 5 ft. Hit: 8 (1d8 + 4) Slashing damage plus 3 (1d6) Poison damage.', 2),
  ('bruxa-verde', 'Spellcasting', 'action'::rpg.actor_action_bucket, 4, NULL, 'The hag casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 12, +4 to hit with spell attacks):', 3),
  ('cambiao', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cambion makes two attacks, using Claw or Fire Ray in any combination.', 1),
  ('cambiao', 'Claw', 'action'::rpg.actor_action_bucket, 7, '8', 'Melee Attack Roll: +7, reach 5 ft. Hit: 8 (1d8 + 4) Slashing damage plus 7 (2d6) Fire damage.', 2),
  ('cambiao', 'Fire Ray', 'action'::rpg.actor_action_bucket, 7, '13', 'Ranged Attack Roll: +7, range 120 ft. Hit: 13 (3d6 + 3) Fire damage.', 3),
  ('cambiao', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cambion casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 14):', 4),
  ('cao-da-morte', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The death dog makes two Bite attacks.', 1),
  ('cao-da-morte', 'Bite', 'action'::rpg.actor_action_bucket, 4, '4', 'Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Piercing damage. If the target is a creature, it is subjected to the following effect. Constitution Saving Throw: DC 12. First Failure: The target has the Poisoned condition. While Poisoned, the target’s Hit Point maximum doesn’t return to normal when finishing a Long Rest, and it repeats the save every 24 hours that elapse, ending the effect on itself on a success. Subsequent Failures: The Poisoned target’s Hit Point maximum decreases by 5 (1d10).', 2),
  ('cao-infernal', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The hound makes two Bite attacks.', 1),
  ('cao-infernal', 'Bite', 'action'::rpg.actor_action_bucket, 5, '7', 'Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Piercing damage plus 3 (1d6) Fire damage.', 2),
  ('cao-infernal', 'Fire Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 12, each creature in a 15-foot Cone. Failure: 17 (5d6) Fire damage. Success: Half damage.', 3),
  ('capitao-da-guarda', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The guard makes two attacks, using Javelin or Longsword in any combination.', 1),
  ('capitao-da-guarda', 'Javelin', 'action'::rpg.actor_action_bucket, 6, '14', 'Melee or Ranged Attack Roll: +6, reach 5 ft. or range 30/120 ft. Hit: 14 (3d6 + 4) Piercing damage.', 2),
  ('capitao-da-guarda', 'Longsword', 'action'::rpg.actor_action_bucket, 6, '15', 'Melee Attack Roll: +6, reach 5 ft. Hit: 15 (2d10 + 4) Slashing damage.', 3),
  ('cataclismo-elemental', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cataclysm makes two Elemental Burst attacks.', 1),
  ('cataclismo-elemental', 'Elemental Burst', 'action'::rpg.actor_action_bucket, 15, '25', 'Melee or Ranged Attack Roll: +15, reach 30 ft. or range 150 ft. Hit: 25 (5d6 + 8) damage of a type chosen by the cataclysm: Acid, Cold, Fire, Lightning, or Thunder.', 2),
  ('cataclismo-elemental', 'Cataclysmic Event (Recharge 4–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cataclysm creates one of the following effects at random (roll 1d4):', 3),
  ('cataclismo-elemental', 'Control Weather', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cataclysm casts the Control Weather spell, requiring no spell components and using Constitution as the spellcasting ability.', 4),
  ('cataclismo-elemental', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3. Immediately after another creature’s turn, the cataclysm can expend a use to take one of the following actions. The cataclysm regains all expended uses at the start of each of its turns.', 5),
  ('cataclismo-elemental', 'Eruption', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The cataclysm makes one Elemental Burst attack.', 6),
  ('cataclismo-elemental', 'Rumbling Movement', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The cataclysm moves up to its Speed, Fly Speed, or Swim Speed without provoking Opportunity Attacks. Each creature within 5 feet of the cataclysm as it moves is targeted once by the following effect. Constitution Saving Throw: DC 23. Failure: The target has the Prone condition. Failure or Success: The cataclysm can’t take this action again until the start of its next turn.', 7),
  ('cavaleiro', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The knight makes two attacks, using Greatsword or Heavy Crossbow in any combination.', 1),
  ('cavaleiro', 'Greatsword', 'action'::rpg.actor_action_bucket, 5, '10', 'Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Slashing damage plus 4 (1d8) Radiant damage.', 2),
  ('cavaleiro', 'Heavy Crossbow', 'action'::rpg.actor_action_bucket, 2, '11', 'Ranged Attack Roll: +2, range 100/400 ft. Hit: 11 (2d10) Piercing damage plus 4 (1d8) Radiant damage.', 3),
  ('cavaleiro', 'Parry', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The knight is hit by a melee attack roll while holding a weapon. Response: The knight adds 2 to its AC against that attack, possibly causing it to miss.', 4),
  ('cavaleiro-da-morte', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The death knight makes three Dread Blade attacks.', 1),
  ('cavaleiro-da-morte', 'Dread Blade', 'action'::rpg.actor_action_bucket, 11, '12', 'Melee Attack Roll: +11, reach 5 ft. Hit: 12 (2d6 + 5) Slashing damage plus 13 (3d8) Necrotic damage.', 2),
  ('cavaleiro-da-morte', 'Hellfire Orb (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 18, each creature in a 20-foot-radius Sphere centered on a point the death knight can see within 120 feet. Failure: 35 (10d6) Fire damage plus 35 (10d6) Necrotic damage. Success: Half damage.', 3),
  ('cavaleiro-da-morte', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The death knight casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 18):', 4),
  ('cavaleiro-da-morte', 'Parry', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The death knight is hit by a melee attack roll while holding a weapon. Response: The death knight adds 6 to its AC against that attack, possibly causing it to miss.', 5),
  ('cavaleiro-da-morte', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3. Immediately after another creature’s turn, the death knight can expend a use to take one of the following actions. The death knight regains all expended uses at the start of each of its turns.', 6),
  ('cavaleiro-da-morte', 'Dread Authority', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The death knight uses Spellcasting to cast Command. The death knight can’t take this action again until the start of its next turn.', 7),
  ('cavaleiro-da-morte', 'Fell Word', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 18, one creature the death knight can see within 120 feet. Failure: 17 (5d6) Necrotic damage, and the target’s Hit Point maximum decreases by an amount equal to the damage taken. Failure or Success: The death knight can’t take this action again until the start of its next turn.', 8),
  ('cavaleiro-da-morte', 'Lunge', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The death knight moves up to half its Speed, and it makes one Dread Blade attack.', 9),
  ('cavaleiro-em-missao', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The knight makes three attacks, using Greatsword or Longbow in any combination.', 1),
  ('cavaleiro-em-missao', 'Greatsword', 'action'::rpg.actor_action_bucket, 9, '12', 'Melee Attack Roll: +9, reach 5 ft. Hit: 12 (2d6 + 5) Slashing damage plus 22 (5d8) Radiant damage.', 2),
  ('cavaleiro-em-missao', 'Longbow', 'action'::rpg.actor_action_bucket, 7, '12', 'Ranged Attack Roll: +7, range 150/600 ft. Hit: 12 (2d8 + 3) Piercing damage plus 22 (5d8) Radiant damage.', 3),
  ('cavaleiro-em-missao', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The knight casts one of the following spells, using Charisma as the spellcasting ability (spell save DC 16):', 4),
  ('centauro-guardiao', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The centaur makes two attacks, using Forest Staff or Sun Ray in any combination.', 1),
  ('centauro-guardiao', 'Forest Staff', 'action'::rpg.actor_action_bucket, 7, '13', 'Melee Attack Roll: +7, reach 5 ft. Hit: 13 (2d8 + 4) Bludgeoning damage plus 14 (4d6) Poison damage.', 2),
  ('centauro-guardiao', 'Sun Ray', 'action'::rpg.actor_action_bucket, 7, '14', 'Ranged Attack Roll: +7, range 90 ft. Hit: 14 (3d6 + 4) Radiant damage, and the target has the Blinded condition until the start of the centaur’s next turn.', 3),
  ('centauro-guardiao', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The centaur casts one of the following spells, using Wisdom as the spellcasting ability (spell save DC 15):', 4),
  ('centauro-guardiao', 'Entangling Trail (Recharge 5–6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The centaur moves up to its Speed without provoking Opportunity Attacks. Each creature within 5 feet of the centaur as it moves is targeted once by the following effect. Strength Saving Throw: DC 15. Failure: 11 (2d6 + 4) Bludgeoning damage, and the target has the Restrained condition until the end of its next turn.', 5),
  ('centauro-soldado', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The centaur makes two attacks, using Pike or Longbow in any combination.', 1),
  ('centauro-soldado', 'Pike', 'action'::rpg.actor_action_bucket, 6, '9', 'Melee Attack Roll: +6, reach 10 ft. Hit: 9 (1d10 + 4) Piercing damage.', 2),
  ('centauro-soldado', 'Longbow', 'action'::rpg.actor_action_bucket, 4, '6', 'Ranged Attack Roll: +4, range 150/600 ft. Hit: 6 (1d8 + 2) Piercing damage.', 3),
  ('centauro-soldado', 'Trampling Charge (Recharge 5–6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The centaur moves up to its Speed without provoking Opportunity Attacks and can move through the spaces of Medium or smaller creatures. Each creature whose space the centaur enters is targeted once by the following effect. Strength Saving Throw: DC 14. Failure: 7 (1d6 + 4) Bludgeoning damage, and the target has the Prone condition.', 4),
  ('chacal-homem', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The jackalwere makes two Rend or Slam attacks.', 1),
  ('chacal-homem', 'Rend (Jackal or Hybrid Form Only)', 'action'::rpg.actor_action_bucket, 4, '5', 'Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Piercing damage.', 2),
  ('chacal-homem', 'Slam (Human or Hybrid Form Only)', 'action'::rpg.actor_action_bucket, 4, '4', 'Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Bludgeoning damage.', 3),
  ('chacal-homem', 'Sleep Gaze (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 10, one creature the jackalwere can see within 30 feet (Constructs and Undead succeed automatically). Failure: The target has the Unconscious condition for 10 minutes or until it takes damage or a creature within 5 feet of it takes an action to wake it. Success: The target is immune to this jackalwere’s Sleep Gaze for 24 hours.', 4),
  ('chacal-homem', 'Shape-Shift', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The jackalwere shape-shifts into a Medium human or a Medium jackal-humanoid hybrid, or it returns to its true form (that of a Small jackal). Other than its size, its game statistics are the same in each form. Any equipment it is wearing or carrying isn’t transformed.', 5),
  ('chasme', 'Proboscis', 'action'::rpg.actor_action_bucket, 5, '16', 'Melee Attack Roll: +5, reach 5 ft. Hit: 16 (4d6 + 2) Piercing damage plus 21 (6d6) Necrotic damage. If the target is a creature, its Hit Point maximum decreases by an amount equal to the Necrotic damage taken.', 1),
  ('chasme', 'Drone', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 12, each creature in a 30-foot Emanation originating from the chasme (demons automatically succeed on this save). Failure: The target has the Unconscious condition and repeats the save at the end of each of its turns. The target succeeds automatically after 10 minutes or if it takes damage or a creature within 5 feet of it takes an action to empty a flask of Holy Water on it. Success: The target is immune to this chasme’s Drone for 24 hours.', 2),
  ('chuul', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The chuul makes two Pincer attacks and uses Paralyzing Tentacles.', 1),
  ('chuul', 'Pincer', 'action'::rpg.actor_action_bucket, 6, '9', 'Melee Attack Roll: +6, reach 10 ft. Hit: 9 (1d10 + 4) Bludgeoning damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 14) from one of two pincers.', 2),
  ('chuul', 'Paralyzing Tentacles', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 13, one creature Grappled by the chuul. Failure: The target has the Poisoned condition and repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically. While Poisoned, the target has the Paralyzed condition.', 3),
  ('ciclope-oraculo', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cyclops makes three attacks, using Radiant Strike or Flash of Light in any combination.', 1),
  ('ciclope-oraculo', 'Radiant Strike', 'action'::rpg.actor_action_bucket, 10, '22', 'Melee Attack Roll: +10, reach 10 ft. Hit: 22 (3d10 + 6) Radiant damage.', 2),
  ('ciclope-oraculo', 'Flash of Light', 'action'::rpg.actor_action_bucket, 10, '17', 'Ranged Attack Roll: +10, range 120 ft. Hit: 17 (2d10 + 6) Radiant damage, and the target has Disadvantage on attack rolls until the end of the cyclops’s next turn.', 3),
  ('ciclope-oraculo', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cyclops casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 16):', 4),
  ('ciclope-oraculo', 'Portent (Recharge 4–6)', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The cyclops or an ally it can see makes a D20 Test. Response: The cyclops rolls 1d20 and chooses whether to use that roll in place of the d20 rolled for the D20 Test.', 5),
  ('ciclope-sentinela', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cyclops makes two attacks, using Stone Club or Rock in any combination.', 1),
  ('ciclope-sentinela', 'Stone Club', 'action'::rpg.actor_action_bucket, 9, '16', 'Melee Attack Roll: +9, reach 10 ft. Hit: 16 (3d6 + 6) Bludgeoning damage. If the target is a Huge or smaller creature, it has the Prone condition.', 2),
  ('ciclope-sentinela', 'Rock', 'action'::rpg.actor_action_bucket, 9, '22', 'Ranged Attack Roll: +9, range 30/120 ft. Hit: 22 (3d10 + 6) Bludgeoning damage.', 3),
  ('ciclope-sentinela', 'Limited Foresight (Recharge 6)', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: A creature the cyclops can see makes an attack roll against it. Response: The cyclops imposes Disadvantage on the roll, and the cyclops gains Advantage on attack rolls against the target until the end of the cyclops’s next turn.', 4),
  ('cocatrice', 'Petrifying Bite', 'action'::rpg.actor_action_bucket, 3, '3', 'Melee Attack Roll: +3, reach 5 ft. Hit: 3 (1d4 + 1) Piercing damage. If the target is a creature, it is subjected to the following effect. Constitution Saving Throw: DC 11. First Failure: The target has the Restrained condition. The target repeats the save at the end of its next turn if it is still Restrained, ending the effect on itself on a success. Second Failure: The target has the Petrified condition, instead of the Restrained condition, for 24 hours.', 1),
  ('cocatrice-regente', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cockatrice makes one Petrifying Bite attack and two Talons attacks.', 1),
  ('cocatrice-regente', 'Petrifying Bite', 'action'::rpg.actor_action_bucket, 7, '13', 'Melee Attack Roll: +7, reach 5 ft. Hit: 13 (2d8 + 4) Piercing damage. If the target is a creature, it is subjected to the following effect. Constitution Saving Throw: DC 14. First Failure: The target has the Restrained condition and repeats the save at the end of its next turn if it is still Restrained, ending the effect on itself on a success. Second Failure: The target has the Petrified condition instead of the Restrained condition.', 2),
  ('cocatrice-regente', 'Talons', 'action'::rpg.actor_action_bucket, 7, '18', 'Melee Attack Roll: +7, reach 5 ft. Hit: 18 (4d6 + 4) Slashing damage.', 3),
  ('cocatrice-regente', 'Magical Backlash', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: A creature within 120 feet of the cockatrice deals damage to it. Response—Dexterity Saving Throw: DC 14, the triggering creature. Failure: 13 (3d6 + 3) Force damage.', 4),
  ('colosso', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The colossus makes three attacks, using Slam or Radiant Ray in any combination.', 1),
  ('colosso', 'Slam', 'action'::rpg.actor_action_bucket, 18, '32', 'Melee Attack Roll: +18, reach 20 ft. Hit: 32 (4d10 + 10) Bludgeoning damage, and the colossus pushes the target up to 20 feet straight away from itself.', 2),
  ('colosso', 'Radiant Ray', 'action'::rpg.actor_action_bucket, 18, '22', 'Ranged Attack Roll: +18, range 300 ft. Hit: 22 (4d10) Radiant damage. If the target is a Large or smaller creature, it has the Prone condition.', 3),
  ('colosso', 'Divine Beam (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 26, each creature in a 300-foot-long, 10-foot-wide Line. Failure: 65 (10d12) Radiant damage. Success: Half damage. Failure or Success: A creature reduced to 0 Hit Points by this beam disintegrates into dust, leaving behind any magic items it was wearing or carrying.', 4),
  ('colosso', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3. Immediately after another creature’s turn, the colossus can expend a use to take one of the following actions. The colossus regains all expended uses at the start of each of its turns.', 5),
  ('colosso', 'Smite', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The colossus makes one Radiant Ray attack.', 6),
  ('colosso', 'Stomp', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The colossus moves up to half its Speed without provoking Opportunity Attacks, and it can make one Slam attack at any point during that move.', 7),
  ('couatl', 'Bite', 'action'::rpg.actor_action_bucket, 7, '11', 'Melee Attack Roll: +7, reach 5 ft. Hit: 11 (1d12 + 5) Piercing damage, and the target has the Poisoned condition until the end of the couatl’s next turn.', 1),
  ('couatl', 'Constrict', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Strength Saving Throw: DC 15, one Medium or smaller creature the couatl can see within 5 feet. Failure: 8 (1d6 + 5) Bludgeoning damage. The target has the Grappled condition (escape DC 13), and it has the Restrained condition until the grapple ends.', 2),
  ('couatl', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The couatl casts one of the following spells, requiring no spell components and using Wisdom as the spellcasting ability (spell save DC 15):', 3),
  ('couatl', 'Divine Aid (2/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The couatl casts Bless, Lesser Restoration, or Sanctuary, requiring no spell components and using the same spellcasting ability as Spellcasting.', 4),
  ('cranio-flamejante', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The flameskull makes two Fire Ray attacks.', 1),
  ('cranio-flamejante', 'Fire Ray', 'action'::rpg.actor_action_bucket, 5, '13', 'Melee or Ranged Attack Roll: +5, reach 5 ft. or range 60 ft. Hit: 13 (3d6 + 3) Fire damage.', 2),
  ('cranio-flamejante', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The flameskull casts one of the following spells, requiring no Somatic or Material components and using Intelligence as the spellcasting ability (spell save DC 13):', 3),
  ('cubo-gelatinoso', 'Pseudopod', 'action'::rpg.actor_action_bucket, 4, '12', 'Melee Attack Roll: +4, reach 5 ft. Hit: 12 (3d6 + 2) Acid damage.', 1),
  ('cubo-gelatinoso', 'Engulf', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cube moves up to its Speed without provoking Opportunity Attacks. The cube can move through the spaces of Large or smaller creatures if it has room inside itself to contain them (see the Ooze Cube trait). Dexterity Saving Throw: DC 12, each creature whose space the cube enters for the first time during this move. Failure: 10 (3d6) Acid damage, and the target is engulfed. An engulfed target is suffocating, can’t cast spells with a Verbal component, has the Restrained condition, and takes 10 (3d6) Acid damage at the start of each of the cube’s turns. When the cube moves, the engulfed target moves with it. An engulfed target can try to escape by taking an action to make a DC 12 Strength (Athletics) check. On a successful check, the target escapes and enters the nearest unoccupied space. Success: Half damage, and the target moves to an unoccupied space within 5 feet of the cube. If there is no unoccupied space, the target fails the save instead.', 2),
  ('cultista', 'Ritual Sickle', 'action'::rpg.actor_action_bucket, 3, '3', 'Melee Attack Roll: +3, reach 5 ft. Hit: 3 (1d4 + 1) Slashing damage plus 1 Necrotic damage.', 1),
  ('cultista-aberrante', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cultist makes two Tentacle Lash attacks. It can replace any attack with a use of Mind Rot.', 1),
  ('cultista-aberrante', 'Tentacle Lash', 'action'::rpg.actor_action_bucket, 7, '7', 'Melee Attack Roll: +7, reach 10 ft. Hit: 7 (1d6 + 4) Slashing damage plus 14 (4d6) Psychic damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 14) from one of two tentacles, and it has the Restrained condition until the grapple ends.', 2),
  ('cultista-aberrante', 'Mind Rot', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 15, one creature the cultist can see within 90 feet. Failure: 27 (6d8) Psychic damage, and the target has the Poisoned condition until the start of the cultist’s next turn. Success: Half damage only.', 3),
  ('cultista-aberrante', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cultist casts one of the following spells, using Wisdom as the spellcasting ability (spell save DC 15):', 4),
  ('cultista-aberrante', 'Counterspell (2/Day)', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'The cultist casts Counterspell in response to that spell’s trigger, using the same spellcasting ability as Spellcasting.', 5),
  ('cultista-da-morte', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cultist makes three attacks, using Dread Scythe or Deathly Ray in any combination.', 1),
  ('cultista-da-morte', 'Dread Scythe', 'action'::rpg.actor_action_bucket, 7, '9', 'Melee Attack Roll: +7, reach 10 ft. Hit: 9 (1d10 + 4) Slashing damage plus 11 (2d10) Necrotic damage, and the target can’t regain Hit Points until the end of its next turn.', 2),
  ('cultista-da-morte', 'Deathly Ray', 'action'::rpg.actor_action_bucket, 6, '22', 'Ranged Attack Roll: +6, range 120 ft. Hit: 22 (4d10) Necrotic damage.', 3),
  ('cultista-da-morte', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cultist casts one of the following spells, using Wisdom as the spellcasting ability (spell save DC 14):', 4),
  ('cultista-da-morte', 'Spirit Wail (Recharge 5–6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 14, each creature in a 20-foot Emanation originating from the cultist. Failure: 14 (4d6) Psychic damage, and the target has the Frightened condition until the end of its next turn. Success: Half damage only.', 5),
  ('cultista-diabolico', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cultist makes three Pact Axe attacks.', 1),
  ('cultista-diabolico', 'Pact Axe', 'action'::rpg.actor_action_bucket, 7, '10', 'Melee Attack Roll: +7, reach 5 ft. Hit: 10 (1d12 + 4) Slashing damage plus 13 (3d8) Fire damage.', 2),
  ('cultista-diabolico', 'Spellcasting', 'action'::rpg.actor_action_bucket, 7, NULL, 'The cultist casts one of the following spells, using Wisdom as the spellcasting ability (spell save DC 15, +7 to hit with spell attacks):', 3),
  ('cultista-diabolico', 'Hellish Rebuke', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'The cultist casts Hellish Rebuke in response to that spell’s trigger, using the same spellcasting ability as Spellcasting.', 4),
  ('cultista-elemental', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cultist makes three attacks, using Elemental Flail or Elemental Claw in any combination.', 1),
  ('cultista-elemental', 'Elemental Flail', 'action'::rpg.actor_action_bucket, 7, '25', 'Melee Attack Roll: +7, reach 5 ft. Hit: 25 (6d6 + 4) damage of a type chosen by the cultist: Acid, Cold, Fire, Lightning, or Thunder.', 2),
  ('cultista-elemental', 'Elemental Claw', 'action'::rpg.actor_action_bucket, 7, '22', 'Ranged Attack Roll: +7, range 120 ft. Hit: 22 (4d10) damage of a type chosen by the cultist: Acid, Cold, Fire, Lightning, or Thunder. If the target is a Medium or smaller creature, the cultist moves the target up to 10 feet straight toward or away from itself.', 3),
  ('cultista-elemental', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cultist casts one of the following spells, using Wisdom as the spellcasting ability (spell save DC 15):', 4),
  ('cultista-elemental', 'Elemental Absorption (1/Day)', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The cultist takes Acid, Cold, Fire, Lightning, or Thunder damage. Response: The cultist gives itself Resistance to that instance of damage and gains 10 Temporary Hit Points.', 5),
  ('cultista-fanatico', 'Pact Blade', 'action'::rpg.actor_action_bucket, 4, '6', 'Melee Attack Roll: +4, reach 5 ft. Hit: 6 (1d8 + 2) Slashing damage plus 7 (2d6) Necrotic damage.', 1),
  ('cultista-fanatico', 'Spellcasting', 'action'::rpg.actor_action_bucket, 4, NULL, 'The cultist casts one of the following spells, using Wisdom as the spellcasting ability (spell save DC 12, +4 to hit with spell attacks):', 2),
  ('cultista-fanatico', 'Spiritual Weapon (2/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The cultist casts the Spiritual Weapon spell, using the same spellcasting ability as Spellcasting.', 3),
  ('cultista-hierofante', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cultist makes three attacks, using Pact Blade or Radiant Ray in any combination.', 1),
  ('cultista-hierofante', 'Pact Blade', 'action'::rpg.actor_action_bucket, 9, '12', 'Melee Attack Roll: +9, reach 5 ft. Hit: 12 (2d6 + 5) Slashing damage plus 18 (4d8) Radiant damage.', 2),
  ('cultista-hierofante', 'Radiant Ray', 'action'::rpg.actor_action_bucket, 9, '31', 'Ranged Attack Roll: +9, range 120 ft. Hit: 31 (4d12 + 5) Radiant damage.', 3),
  ('cultista-hierofante', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cultist casts one of the following spells, using Charisma as the spellcasting ability (spell save DC 17):', 4),
  ('dao', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dao makes three Earthen Maul attacks or two Earth Burst attacks.', 1),
  ('dao', 'Earthen Maul', 'action'::rpg.actor_action_bucket, 10, '20', 'Melee Attack Roll: +10, reach 5 ft. Hit: 20 (4d6 + 6) Bludgeoning damage. If the target is a Large or smaller creature, it has the Prone condition.', 2),
  ('dao', 'Earth Burst', 'action'::rpg.actor_action_bucket, 10, '15', 'Ranged Attack Roll: +10, range 120 ft. Hit: 15 (2d8 + 6) Bludgeoning damage. Hit or Miss: Earth explodes from the target’s space, creating the following effect. Dexterity Saving Throw: DC 16, each creature in a 10-foot Emanation originating from and including the target. Failure: 10 (3d6) Thunder damage.', 3),
  ('dao', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dao casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 16):', 4),
  ('deva', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The deva makes two Holy Mace attacks.', 1),
  ('deva', 'Holy Mace', 'action'::rpg.actor_action_bucket, 8, '7', 'Melee Attack Roll: +8, reach 5 ft. Hit: 7 (1d6 + 4) Bludgeoning damage plus 18 (4d8) Radiant damage.', 2),
  ('deva', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The deva casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 17):', 3),
  ('deva', 'Divine Aid (2/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The deva casts Cure Wounds, Lesser Restoration, or Remove Curse, using the same spellcasting ability as Spellcasting.', 4),
  ('devorador-de-intelecto', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The intellect devourer makes one Claw attack and uses Devour Intellect.', 1),
  ('devorador-de-intelecto', 'Claw', 'action'::rpg.actor_action_bucket, 4, '7', 'Melee Attack Roll: +4, reach 5 ft. Hit: 7 (2d4 + 2) Slashing damage.', 2),
  ('devorador-de-intelecto', 'Devour Intellect', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Intelligence Saving Throw: DC 12, one creature the intellect devourer can see within 5 feet. Failure: 11 (2d10) Psychic damage, and the target has the Stunned condition until the end of the intellect devourer’s next turn.', 3),
  ('devorador-de-intelecto', 'Steal Body', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Intelligence Saving Throw: DC 12, one Small or Medium creature within 5 feet that has the Incapacitated condition, is a Humanoid or Beast, and has 10 Hit Points or fewer. Failure: The intellect devourer possesses the target, consumes its brain, and teleports inside its skull. While there, the intellect devourer has Total Cover against attacks and other effects originating outside its host. The intellect devourer retains its Intelligence, Wisdom, and Charisma scores; its understanding of Deep Speech; its telepathy; and its Detect Intelligence trait. It otherwise adopts the target’s game statistics. It knows everything the target knew, including spells and languages.', 4),
  ('diabo-acorrentado', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The devil makes two Chain attacks and uses Conjure Infernal Chain.', 1),
  ('diabo-acorrentado', 'Chain', 'action'::rpg.actor_action_bucket, 7, '11', 'Melee Attack Roll: +7, reach 10 ft. Hit: 11 (2d6 + 4) Slashing damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 14) from one of two chains, and it has the Restrained condition until the grapple ends.', 2),
  ('diabo-acorrentado', 'Conjure Infernal Chain', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The devil conjures a fiery chain to bind a creature. Dexterity Saving Throw: DC 15, one creature the devil can see within 60 feet. Failure: 9 (2d4 + 4) Fire damage, and the target has the Restrained condition until the end of the devil’s next turn, at which point the chain disappears. If the target is Large or smaller, the devil moves the target up to 30 feet straight toward itself. Success: The chain disappears.', 3),
  ('diabo-acorrentado', 'Unnerving Gaze', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: A creature the devil can see starts its turn within 30 feet of the devil and can see the devil. Response—Wisdom Saving Throw: DC 15, the triggering creature. Failure: The target has the Frightened condition until the end of its turn. Success: The target is immune to this devil’s Unnerving Gaze for 24 hours.', 4),
  ('diabo-cornudo', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The devil makes three attacks, using Searing Fork or Hurl Flame in any combination. It can replace one attack with a use of Infernal Tail.', 1),
  ('diabo-cornudo', 'Searing Fork', 'action'::rpg.actor_action_bucket, 10, '15', 'Melee Attack Roll: +10, reach 10 ft. Hit: 15 (2d8 + 6) Piercing damage plus 9 (2d8) Fire damage.', 2),
  ('diabo-cornudo', 'Hurl Flame', 'action'::rpg.actor_action_bucket, 8, '26', 'Ranged Attack Roll: +8, range 150 ft. Hit: 26 (5d8 + 4) Fire damage. If the target is a flammable object that isn’t being worn or carried, it starts burning.', 3),
  ('diabo-cornudo', 'Infernal Tail', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 17, one creature the devil can see within 10 feet. Failure: 10 (1d8 + 6) Necrotic damage, and the target receives an infernal wound if it doesn’t have one. While wounded, the target loses 10 (3d6) Hit Points at the start of each of its turns. The wound closes after 1 minute, after a spell restores Hit Points to the target, or after the target or a creature within 5 feet of it takes an action to stanch the wound, doing so by succeeding on a DC 17 Wisdom (Medicine) check.', 4),
  ('diabo-do-gelo', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The devil makes three Ice Spear attacks. It can replace one attack with a Tail attack.', 1),
  ('diabo-do-gelo', 'Ice Spear', 'action'::rpg.actor_action_bucket, 10, '14', 'Melee or Ranged Attack Roll: +10, reach 5 ft. or range 30/120 ft. Hit: 14 (2d8 + 5) Piercing damage plus 10 (3d6) Cold damage. Until the end of its next turn, the target can’t take a Bonus Action or Reaction, its Speed decreases by 10 feet, and it can move or take one action on its turn, not both. Hit or Miss: The spear magically returns to the devil’s hand immediately after a ranged attack.', 2),
  ('diabo-do-gelo', 'Tail', 'action'::rpg.actor_action_bucket, 10, '15', 'Melee Attack Roll: +10, reach 10 ft. Hit: 15 (3d6 + 5) Bludgeoning damage plus 18 (4d8) Cold damage.', 3),
  ('diabo-do-gelo', 'Ice Wall (Recharge 6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The devil casts Wall of Ice (level 8 version), requiring no spell components and using Intelligence as the spellcasting ability (spell save DC 17).', 4),
  ('diabrete', 'Sting', 'action'::rpg.actor_action_bucket, 5, '6', 'Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Piercing damage plus 7 (2d6) Poison damage.', 1),
  ('diabrete', 'Invisibility', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The imp casts Invisibility on itself, requiring no spell components and using Charisma as the spellcasting ability.', 2),
  ('diabrete', 'Shape-Shift', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The imp shape-shifts to resemble a rat (Speed 20 ft.), a raven (20 ft., Fly 60 ft.), or a spider (20 ft., Climb 20 ft.), or it returns to its true form. Its game statistics are the same in each form, except for its Speed. Any equipment it is wearing or carrying isn’t transformed.', 3),
  ('djinn', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The djinni makes three attacks, using Storm Blade or Storm Bolt in any combination.', 1),
  ('djinn', 'Storm Blade', 'action'::rpg.actor_action_bucket, 9, '12', 'Melee Attack Roll: +9, reach 5 feet. Hit: 12 (2d6 + 5) Slashing damage plus 7 (2d6) Lightning damage.', 2),
  ('djinn', 'Storm Bolt', 'action'::rpg.actor_action_bucket, 9, '13', 'Ranged Attack Roll: +9, range 120 feet. Hit: 13 (3d8) Thunder damage. If the target is a Large or smaller creature, it has the Prone condition.', 3),
  ('djinn', 'Create Whirlwind', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The djinni conjures a whirlwind at a point it can see within 120 feet. The whirlwind fills a 20-foot-radius, 60-foot-high Cylinder centered on that point. The whirlwind lasts until the djinni’s Concentration on it ends. The djinni can move the whirlwind up to 20 feet at the start of each of its turns.', 4),
  ('djinn', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The djinni casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 17):', 5),
  ('doppelganger', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The doppelganger makes two Slam attacks and uses Unsettling Visage if available.', 1),
  ('doppelganger', 'Slam', 'action'::rpg.actor_action_bucket, 6, '11', 'Melee Attack Roll: +6 (with Advantage during the first round of each combat), reach 5 ft. Hit: 11 (2d6 + 4) Bludgeoning damage.', 2),
  ('doppelganger', 'Read Thoughts', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The doppelganger casts Detect Thoughts, requiring no spell components and using Charisma as the spellcasting ability (spell save DC 12).', 3),
  ('doppelganger', 'Unsettling Visage (Recharge 6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 12, each creature in a 15-foot Emanation originating from the doppelganger that can see the doppelganger. Failure: The target has the Frightened condition and repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically.', 4),
  ('doppelganger', 'Shape-Shift', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The doppelganger shape-shifts into a Medium or Small Humanoid, or it returns to its true form. Its game statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn’t transformed.', 5),
  ('dracolich', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dracolich makes three Rend attacks. It can replace one attack with a use of Spellcasting to cast Ray of Sickness (level 2 version).', 1),
  ('dracolich', 'Rend', 'action'::rpg.actor_action_bucket, 13, '18', 'Melee Attack Roll: +13, reach 10 ft. Hit: 18 (2d10 + 7) Slashing damage plus 4 (1d8) Necrotic damage.', 2),
  ('dracolich', 'Necrotic Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 20, each creature in a 60-foot Cone. Failure: 52 (8d12) Necrotic damage. Success: Half damage.', 3),
  ('dracolich', 'Spellcasting', 'action'::rpg.actor_action_bucket, 11, NULL, 'The dracolich casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 19, +11 to hit with spell attacks):', 4),
  ('dracolich', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature’s turn, the dracolich can expend a use to take one of the following actions. The dracolich regains all expended uses at the start of each of its turns.', 5),
  ('dracolich', 'Pounce', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dracolich moves up to half its Speed, and it makes one Rend attack.', 6),
  ('dracolich', 'Sickening Ray', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dracolich uses Spellcasting to cast Ray of Sickness (level 2 version). The dracolich can’t take this action again until the start of its next turn.', 7),
  ('dracolich', 'Terrifying Presence', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 19, each creature in a 30-foot Emanation originating from the dracolich. Failure: 11 (2d10) Psychic damage, and the target has the Frightened condition until the end of its next turn. Failure or Success: The dracolich can’t take this action again until the start of its next turn.', 8),
  ('dragao-de-cobre-adulto', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon makes three Rend attacks. It can replace one attack with a use of (A) Slowing Breath or (B) Spellcasting to cast Mind Spike (level 4 version).', 1),
  ('dragao-de-cobre-adulto', 'Rend', 'action'::rpg.actor_action_bucket, 11, '17', 'Melee Attack Roll: +11, reach 10 ft. Hit: 17 (2d10 + 6) Slashing damage plus 4 (1d8) Acid damage.', 2),
  ('dragao-de-cobre-adulto', 'Acid Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 18, each creature in an 60-foot-long, 5-foot-wide Line. Failure: 54 (12d8) Acid damage. Success: Half damage.', 3),
  ('dragao-de-cobre-adulto', 'Slowing Breath', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 18, each creature in a 60-foot Cone. Failure: The target can’t take Reactions; its Speed is halved; and it can take either an action or a Bonus Action on its turn, not both. This effect lasts until the end of its next turn.', 4),
  ('dragao-de-cobre-adulto', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 17):', 5),
  ('dragao-de-cobre-adulto', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature’s turn, the dragon can expend a use to take one of the following actions. The dragon regains all expended uses at the start of each of its turns.', 6),
  ('dragao-de-cobre-adulto', 'Giggling Magic', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'Charisma Saving Throw: DC 17, one creature the dragon can see within 90 feet. Failure: 24 (7d6) Psychic damage. Until the end of its next turn, the target rolls 1d6 whenever it makes an ability check or attack roll and subtracts the number rolled from the D20 Test. Failure or Success: The dragon can’t take this action again until the start of its next turn.', 7),
  ('dragao-de-cobre-adulto', 'Mind Jolt', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon uses Spellcasting to cast Mind Spike (level 4 version). The dragon can’t take this action again until the start of its next turn.', 8),
  ('dragao-de-cobre-adulto', 'Pounce', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon moves up to half its Speed, and it makes one Rend attack.', 9),
  ('dragao-de-cobre-anciano', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon makes three Rend attacks. It can replace one attack with a use of (A) Slowing Breath or (B) Spellcasting to cast Mind Spike (level 5 version).', 1),
  ('dragao-de-cobre-anciano', 'Rend', 'action'::rpg.actor_action_bucket, 15, '19', 'Melee Attack Roll: +15, reach 15 ft. Hit: 19 (2d10 + 8) Slashing damage plus 9 (2d8) Acid damage.', 2),
  ('dragao-de-cobre-anciano', 'Acid Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 22, each creature in an 90-foot-long, 10-foot-wide Line. Failure: 63 (14d8) Acid damage. Success: Half damage.', 3),
  ('dragao-de-cobre-anciano', 'Slowing Breath', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 22, each creature in a 90-foot Cone. Failure: The target can’t take Reactions; its Speed is halved; and it can take either an action or a Bonus Action on its turn, not both. This effect lasts until the end of its next turn.', 4),
  ('dragao-de-cobre-anciano', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 21):', 5),
  ('dragao-de-cobre-anciano', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature’s turn, the dragon can expend a use to take one of the following actions. The dragon regains all expended uses at the start of each of its turns.', 6),
  ('dragao-de-cobre-anciano', 'Giggling Magic', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'Charisma Saving Throw: DC 21, one creature the dragon can see within 120 feet. Failure: 31 (9d6) Psychic damage. Until the end of its next turn, the target rolls 1d8 whenever it makes an ability check or attack roll and subtracts the number rolled from the D20 Test. Failure or Success: The dragon can’t take this action again until the start of its next turn.', 7),
  ('dragao-de-cobre-anciano', 'Mind Jolt', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The dragon uses Spellcasting to cast Mind Spike (level 5 version). The dragon can’t take this action again until the start of its next turn.', 8),
