  ('erinia', 'Entangling Rope (Requires Magic Rope)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Strength Saving Throw: DC 16, one creature the erinyes can see within 120 feet. Failure: 14 (4d6) Force damage, and the target has the Restrained condition until the rope is destroyed, the erinyes uses a Bonus Action to release the target, or the erinyes uses Entangling Rope again.', 3),
  ('erinia', 'Parry', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The erinyes is hit by a melee attack roll while holding a weapon. Response: The erinyes adds 4 to its AC against that attack, possibly causing it to miss.', 4),
  ('ettercap', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The ettercap makes one Bite attack and one Claw attack.', 1),
  ('ettercap', 'Bite', 'action'::rpg.actor_action_bucket, 4, '5', 'Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Piercing damage plus 2 (1d4) Poison damage, and the target has the Poisoned condition until the start of the ettercap’s next turn.', 2),
  ('ettercap', 'Claw', 'action'::rpg.actor_action_bucket, 4, '7', 'Melee Attack Roll: +4, reach 5 ft. Hit: 7 (2d4 + 2) Slashing damage.', 3),
  ('ettercap', 'Web Strand (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 12, one Large or smaller creature the ettercap can see within 30 feet. Failure: The target has the Restrained condition until the web is destroyed (AC 10; HP 5; Vulnerability to Fire damage; Immunity to Bludgeoning, Poison, and Psychic damage).', 4),
  ('ettercap', 'Reel', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The ettercap pulls one creature within 30 feet of itself that is Restrained by its Web Strand up to 25 feet straight toward itself.', 5),
  ('ettin', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The ettin makes one Battleaxe attack and one Morningstar attack.', 1),
  ('ettin', 'Battleaxe', 'action'::rpg.actor_action_bucket, 7, '14', 'Melee Attack Roll: +7, reach 5 ft. Hit: 14 (2d8 + 5) Slashing damage. If the target is a Large or smaller creature, it has the Prone condition.', 2),
  ('ettin', 'Morningstar', 'action'::rpg.actor_action_bucket, 7, '14', 'Melee Attack Roll: +7, reach 5 ft. Hit: 14 (2d8 + 5) Piercing damage, and the target has Disadvantage on the next attack roll it makes before the end of its next turn.', 3),
  ('fantasma', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The ghost makes two Withering Touch attacks.', 1),
  ('fantasma', 'Withering Touch', 'action'::rpg.actor_action_bucket, 5, '19', 'Melee Attack Roll: +5, reach 5 ft. Hit: 19 (3d10 + 3) Necrotic damage.', 2),
  ('fantasma', 'Etherealness', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The ghost casts the Etherealness spell, requiring no spell components and using Charisma as the spellcasting ability. The ghost is visible on the Material Plane while on the Border Ethereal and vice versa, but it can’t affect or be affected by anything on the other plane.', 3),
  ('fantasma', 'Horrific Visage', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 13, each creature in a 60-foot Cone that can see the ghost and isn’t an Undead. Failure: 10 (2d6 + 3) Psychic damage, and the target has the Frightened condition until the start of the ghost’s next turn. Success: The target is immune to this ghost’s Horrific Visage for 24 hours.', 4),
  ('fantasma', 'Possession (Recharge 6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Charisma Saving Throw: DC 13, one Humanoid the ghost can see within 5 feet. Failure: The target is possessed by the ghost; the ghost disappears, and the target has the Incapacitated condition and loses control of its body. The ghost now controls the body, but the target retains awareness. The ghost can’t be targeted by any attack, spell, or other effect, except ones that specifically target Undead. The ghost’s game statistics are the same, except it uses the possessed target’s Speed, as well as the target’s Strength, Dexterity, and Constitution modifiers.', 5),
  ('fera-deslocadora', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The displacer beast makes one Rend attack and one Tentacle attack.', 1),
  ('fera-deslocadora', 'Rend', 'action'::rpg.actor_action_bucket, 6, '9', 'Melee Attack Roll: +6, reach 5 feet. Hit: 9 (1d10 + 4) Slashing damage. If target is a Large or smaller creature, it has the Prone condition.', 2),
  ('fera-deslocadora', 'Tentacle', 'action'::rpg.actor_action_bucket, 6, '11', 'Melee Attack Roll: +6, reach 10 feet. Hit: 11 (2d6 + 4) Piercing damage.', 3),
  ('flumph', 'Tentacle', 'action'::rpg.actor_action_bucket, 4, '4', 'Melee Attack Roll: +4, reach 5 feet. Hit: 4 (1d4 + 2) Acid damage.', 1),
  ('flumph', 'Stench Spray (1/Day)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 10, one creature the flumph can see within 15 feet. Failure: The target is coated in a foul-smelling liquid, exudes a stench for 1d4 hours, and has the Poisoned condition while the stench lasts. Other creatures have the Poisoned condition while in a 5-foot Emanation originating from the coated target. The target can remove the stench on itself if it bathes during a Short or Long Rest.', 2),
  ('fomore', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The fomorian makes two Stone Club attacks. It can replace one attack with a use of Warping Hex if available.', 1),
  ('fomore', 'Stone Club', 'action'::rpg.actor_action_bucket, 9, '24', 'Melee Attack Roll: +9, reach 15 ft. Hit: 24 (4d8 + 6) Bludgeoning damage.', 2),
  ('fomore', 'Warping Hex (Recharge 4–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 16, one creature the fomorian can see within 120 feet. Failure: 21 (6d6) Psychic damage, and the target gains 1 Exhaustion level. Success: Half damage only.', 3),
  ('fungo-esporo-de-gas', 'Tendril', 'action'::rpg.actor_action_bucket, 0, '3', 'Melee Attack Roll: +0, reach 5 ft. Hit: 3 (1d6) Poison damage, and the target has the Poisoned condition until the end of its next turn.', 1),
  ('fungo-gritador', 'Shriek', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: A creature or a source of Bright Light moves within 30 feet of the shrieker. Response: The shrieker emits a shriek audible within 300 feet of itself for 1 minute or until the shrieker dies.', 1),
  ('fungo-violeta', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The fungus makes two Rotting Touch attacks.', 1),
  ('fungo-violeta', 'Rotting Touch', 'action'::rpg.actor_action_bucket, 2, '4', 'Melee Attack Roll: +2, reach 10 ft. Hit: 4 (1d8) Necrotic damage.', 2),
  ('fungo-violeta-necrohulk', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The necrohulk makes two Rotting Slam attacks.', 1),
  ('fungo-violeta-necrohulk', 'Rotting Slam', 'action'::rpg.actor_action_bucket, 7, '9', 'Melee Attack Roll: +7, reach 10 ft. Hit: 9 (1d10 + 4) Bludgeoning damage plus 7 (2d6) Necrotic damage.', 2),
  ('fungo-violeta-necrohulk', 'Spore Bomb (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 15, each creature in a 20-foot-radius Sphere centered on a point the necrohulk can see within 60 feet. Failure: 28 (8d6) Necrotic damage, and the target has the Poisoned condition until the start of the necrohulk’s next turn. While Poisoned, the target can’t regain Hit Points. Success: Half damage only.', 3),
  ('fungo-violeta-necrohulk', 'Absorb Body', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Strength Saving Throw: DC 15, one Medium or Small creature the necrohulk can see within 5 feet. Failure: The target is pulled into the necrohulk’s space and becomes grafted to its body. The necrohulk can have only one target grafted at a time.', 4),
  ('galeb-duhr', 'Avalanche Slam', 'action'::rpg.actor_action_bucket, 8, '12', 'Melee Attack Roll: +8, reach 5 ft. Hit: 12 (2d6 + 5) Bludgeoning damage. If the target is a Large or smaller creature and the galeb duhr moved 20+ feet straight toward it immediately before the hit, the target takes an extra 7 (2d6) Bludgeoning damage and has the Prone condition.', 1),
  ('galeb-duhr', 'Animate Boulders (1/Day)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The galeb duhr magically animates one or two boulders it can see within 60 feet of itself. Each boulder uses the Galeb Duhr stat block, except it has Intelligence and Charisma scores of 1 and lacks this action. The boulder takes its turn immediately after the galeb duhr on the same Initiative count, and it obeys the galeb duhr. A boulder remains animate for 1 minute or until it or the galeb duhr dies.', 2),
  ('gargula', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The gargoyle makes two Claw attacks.', 1),
  ('gargula', 'Claw', 'action'::rpg.actor_action_bucket, 4, '7', 'Melee Attack Roll: +4, reach 5 ft. Hit: 7 (2d4 + 2) Slashing damage.', 2),
  ('garra-rastejante', 'Slam', 'action'::rpg.actor_action_bucket, 3, '2', 'Melee Attack Roll: +3, reach 5 ft. Hit: 2 Necrotic damage.', 1),
  ('ghast', 'Bite', 'action'::rpg.actor_action_bucket, 5, '7', 'Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Piercing damage plus 9 (2d8) Necrotic damage.', 1),
  ('ghast', 'Claw', 'action'::rpg.actor_action_bucket, 5, '10', 'Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Slashing damage. If the target is a non-Undead creature, it is subjected to the following effect. Constitution Saving Throw: DC 10. Failure: The target has the Paralyzed condition until the end of its next turn.', 2),
  ('ghast-chamador-de-tumulos', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The ghast makes two Horrific Necrosis attacks. It can replace one attack with a Claw attack.', 1),
  ('ghast-chamador-de-tumulos', 'Claw', 'action'::rpg.actor_action_bucket, 6, '13', 'Melee Attack Roll: +6, reach 5 ft. Hit: 13 (3d6 + 3) Slashing damage. If the target isn’t an Undead, it has the Paralyzed condition until the end of its next turn.', 2),
  ('ghast-chamador-de-tumulos', 'Horrific Necrosis', 'action'::rpg.actor_action_bucket, 7, '15', 'Melee or Ranged Attack Roll: +7, reach 5 ft. or range 120 ft. Hit: 15 (2d10 + 4) Necrotic damage, and the target has the Frightened condition until the end of its next turn.', 3),
  ('ghast-chamador-de-tumulos', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The ghast casts one of the following spells, requiring no Material components and using Intelligence as the spellcasting ability:', 4),
