  ('ghoul', 'Bite', 'action'::rpg.actor_action_bucket, 4, '5', 'Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Piercing damage plus 3 (1d6) Necrotic damage.', 2),
  ('ghoul', 'Claw', 'action'::rpg.actor_action_bucket, 4, '4', 'Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Slashing damage. If the target is a creature that isn’t an Undead or elf, it is subjected to the following effect. Constitution Saving Throw: DC 10. Failure: The target has the Paralyzed condition until the end of its next turn.', 3),
  ('ghoul-lacedon', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The ghoul makes two Icy Bite attacks.', 1),
  ('ghoul-lacedon', 'Icy Bite', 'action'::rpg.actor_action_bucket, 4, '9', 'Melee Attack Roll: +4, reach 5 ft. Hit: 9 (2d6 + 2) Cold damage, and the target’s Speed decreases by 5 feet until the start of the ghoul’s next turn.', 2),
  ('ghoul-lacedon', 'Claw', 'action'::rpg.actor_action_bucket, 4, '4', 'Melee Attack Roll: +4, reach 5 ft. Hit: 4 (1d4 + 2) Slashing damage. If the target is a creature that isn’t an Undead or elf, it is subjected to the following effect. Constitution Saving Throw: DC 10. Failure: The target has the Paralyzed condition until the end of its next turn.', 3),
  ('ghoul-lacedon', 'Watery Rush', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'While underwater, the ghoul moves up to half its Swim Speed without provoking Opportunity Attacks.', 4),
  ('gigante-das-colinas', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The giant makes two attacks, using Tree Club or Trash Lob in any combination.', 1),
  ('gigante-das-colinas', 'Tree Club', 'action'::rpg.actor_action_bucket, 8, '18', 'Melee Attack Roll: +8, reach 10 ft. Hit: 18 (3d8 + 5) Bludgeoning damage. If the target is a Large or smaller creature, it has the Prone condition.', 2),
  ('gigante-das-colinas', 'Trash Lob', 'action'::rpg.actor_action_bucket, 8, '16', 'Ranged Attack Roll: +8, range 60/240 ft. Hit: 16 (2d10 + 5) Bludgeoning damage, and the target has the Poisoned condition until the end of its next turn.', 3),
  ('gigante-das-nuvens', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The giant makes two attacks, using Thunderous Mace or Thundercloud in any combination. It can replace one attack with a use of Spellcasting to cast Fog Cloud.', 1),
  ('gigante-das-nuvens', 'Thunderous Mace', 'action'::rpg.actor_action_bucket, 12, '21', 'Melee Attack Roll: +12, reach 10 ft. Hit: 21 (3d8 + 8) Bludgeoning damage plus 7 (2d6) Thunder damage.', 2),
  ('gigante-das-nuvens', 'Thundercloud', 'action'::rpg.actor_action_bucket, 12, '18', 'Ranged Attack Roll: +12, range 240 ft. Hit: 18 (3d6 + 8) Thunder damage, and the target has the Incapacitated condition until the end of its next turn.', 3),
  ('gigante-das-nuvens', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The giant casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 15):', 4),
  ('gigante-das-nuvens', 'Misty Step', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The giant casts the Misty Step spell, using the same spellcasting ability as Spellcasting.', 5),
