  ('gigante-do-fogo', 'Flame Sword', 'action'::rpg.actor_action_bucket, 11, '21', 'Melee Attack Roll: +11, reach 10 ft. Hit: 21 (4d6 + 7) Slashing damage plus 10 (3d6) Fire damage.', 2),
  ('gigante-do-fogo', 'Hammer Throw', 'action'::rpg.actor_action_bucket, 11, '23', 'Ranged Attack Roll: +11, range 60/240 ft. Hit: 23 (3d10 + 7) Bludgeoning damage plus 4 (1d8) Fire damage, and the target is pushed up to 15 feet straight away from the giant and has Disadvantage on the next attack roll it makes before the end of its next turn.', 3),
