  ('gigante-do-gelo', 'War Cry (Recharge 5–6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The giant or one creature of its choice that can see or hear it gains 16 (2d10 + 5) Temporary Hit Points and has Advantage on attack rolls until the start of the giant’s next turn.', 4),
  ('githyanki-cavaleiro', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The githyanki makes three Silver Sword attacks. It can replace one attack with a use of Spellcasting to cast Telekinesis if available.', 1),
  ('githyanki-cavaleiro', 'Silver Sword', 'action'::rpg.actor_action_bucket, 6, '10', 'Melee Attack Roll: +6, reach 5 ft. Hit: 10 (2d6 + 3) Slashing damage plus 14 (4d6) Psychic damage. Critical Hit: If the target is in an astral body (as with the Astral Projection spell), the githyanki can cut the silvery cord that tethers the target to its material body instead of dealing damage.', 2),
  ('githyanki-cavaleiro', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The githyanki casts one of the following spells, requiring no spell components and using Intelligence as the spellcasting ability (spell save DC 13):', 3),
  ('githyanki-cavaleiro', 'Misty Step (2/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The githyanki casts Misty Step, requiring no spell components and using the same spellcasting ability as Spellcasting.', 4),
  ('githyanki-dracomante', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The githyanki makes three Draconic Strike attacks.', 1),
