  ('githyanki-dracomante', 'Conjured Dragon’s Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 18, each creature in a 90-foot Cone. Failure: 27 (6d8) Fire damage plus 27 (6d8) Force damage. Success: Half damage.', 3),
