  ('gnoll-demoniaco', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The gnoll makes two Abyssal Strike attacks.', 1),
  ('gnoll-demoniaco', 'Abyssal Strike', 'action'::rpg.actor_action_bucket, 6, '20', 'Melee or Ranged Attack Roll: +6, reach 5 ft. or range 60 ft. Hit: 20 (5d6 + 3) Poison damage.', 2),
  ('gnoll-demoniaco', 'Hunger of Yeenoghu (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The gnoll conjures a 30-foot Cube of magical Darkness originating from a point it can see within 60 feet, which lasts for 1 minute or until the gnoll’s Concentration ends on it. This area is Difficult Terrain. Dexterity Saving Throw: DC 14, any creature that starts its turn in this area or enters it for the first time on a turn. Failure: 28 (8d6) Necrotic damage, and the gnoll or a creature of its choice it can see gains 10 Temporary Hit Points. Success: Half damage only.', 3),
  ('gnoll-demoniaco', 'Rampage (2/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Immediately after dealing damage to a creature that is already Bloodied, the gnoll moves up to half its Speed, and it makes one Abyssal Strike attack.', 4),
