  ('goblin-amaldicoador', 'Jinx', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: A creature the goblin can see hits it with an attack roll. Response—Wisdom Saving Throw: DC 13, the triggering creature. Failure: The attack misses instead.', 4),
