  ('goblin-chefe', 'Shortbow', 'action'::rpg.actor_action_bucket, 4, '5', 'Ranged Attack Roll: +4, range 80/320 ft. Hit: 5 (1d6 + 2) Piercing damage, plus 2 (1d4) Piercing damage if the attack roll had Advantage.', 3),
  ('goblin-chefe', 'Nimble Escape', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The goblin takes the Disengage or Hide action.', 4),
  ('goblin-chefe', 'Redirect Attack', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: A creature the goblin can see makes an attack roll against it. Response: The goblin chooses a Small or Medium ally within 5 feet of itself. The goblin and that ally swap places, and the ally becomes the target of the attack instead.', 5),
  ('goblin-guerreiro', 'Scimitar', 'action'::rpg.actor_action_bucket, 4, '5', 'Melee Attack Roll: +4, reach 5 ft. Hit: 5 (1d6 + 2) Slashing damage, plus 2 (1d4) Slashing damage if the attack roll had Advantage.', 1),
