  ('goblin-lacaio', 'Nimble Escape', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The goblin takes the Disengage or Hide action.', 2),
  ('golem-de-argila', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The golem makes two Slam attacks, or it makes three Slam attacks if it used Hasten this turn.', 1),
  ('golem-de-argila', 'Slam', 'action'::rpg.actor_action_bucket, 9, '10', 'Melee Attack Roll: +9, reach 5 ft. Hit: 10 (1d10 + 5) Bludgeoning damage plus 6 (1d12) Acid damage, and the target’s Hit Point maximum decreases by an amount equal to the Acid damage taken.', 2),
  ('golem-de-argila', 'Hasten (Recharge 5–6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The golem takes the Dash and Disengage actions.', 3),
  ('golem-de-carne', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The golem makes two Slam attacks.', 1),
  ('golem-de-carne', 'Slam', 'action'::rpg.actor_action_bucket, 7, '13', 'Melee Attack Roll: +7, reach 5 ft. Hit: 13 (2d8 + 4) Bludgeoning damage plus 4 (1d8) Lightning damage.', 2),
  ('golem-de-ferro', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The golem makes two attacks, using Bladed Arm or Fiery Bolt in any combination.', 1),
  ('golem-de-ferro', 'Bladed Arm', 'action'::rpg.actor_action_bucket, 12, '20', 'Melee Attack Roll: +12, reach 10 ft. Hit: 20 (3d8 + 7) Slashing damage plus 10 (3d6) Fire damage.', 2),
  ('golem-de-ferro', 'Fiery Bolt', 'action'::rpg.actor_action_bucket, 10, '36', 'Ranged Attack Roll: +10, range 120 ft. Hit: 36 (8d8) Fire damage.', 3),
  ('golem-de-ferro', 'Poison Breath (Recharge 6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 18, each creature in a 60-foot Cone. Failure: 55 (10d10) Poison damage. Success: Half damage.', 4),
  ('gorgone', 'Gore', 'action'::rpg.actor_action_bucket, 8, '18', 'Melee Attack Roll: +8, reach 5 ft. Hit: 18 (2d12 + 5) Piercing damage. If the target is a Large or smaller creature and the gorgon moved 20+ feet straight toward it immediately before the hit, the target has the Prone condition.', 1),
  ('gorgone', 'Petrifying Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 15, each creature in a 30-foot Cone. First Failure: The target has the Restrained condition and repeats the save at the end of its next turn if it is still Restrained, ending the effect on itself on a success. Second Failure: The target has the Petrified condition instead of the Restrained condition.', 2),
  ('gorgone', 'Trample', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 16, one creature within 5 feet that has the Prone condition. Failure: 16 (2d10 + 5) Bludgeoning damage. Success: Half damage.', 3),
  ('gorgone-de-bronze', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The gorgon makes two Gore attacks.', 1),
  ('gorgone-de-bronze', 'Gore', 'action'::rpg.actor_action_bucket, 8, '11', 'Melee Attack Roll: +8, reach 5 ft. Hit: 11 (2d6 + 4) Piercing damage plus 10 (3d6) Fire damage.', 2),
  ('gorgone-de-bronze', 'Smelting Charge (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The gorgon moves up to its Speed without provoking Opportunity Attacks and can move through the spaces of Medium or smaller creatures. Each time the gorgon enters a creature’s space for the first time during this move, that target is subjected to the following effect. Dexterity Saving Throw: DC 16. Failure: 13 (2d8 + 4) Piercing damage plus 13 (3d8) Fire damage, and the target is pulled into the gorgon’s space and has the Grappled condition (escape DC 14); if the gorgon already has a creature Grappled, the target has the Prone condition instead. Until the grapple ends, the target has the Restrained condition. When the gorgon moves, the Grappled target moves with it, costing no extra movement.', 3),
  ('goristro', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The goristro makes one Brutal Gore attack and two Slam attacks.', 1),
  ('goristro', 'Brutal Gore', 'action'::rpg.actor_action_bucket, 13, '40', 'Melee Attack Roll: +13, reach 10 ft. Hit: 40 (6d10 + 7) Piercing damage. If the target is a Huge or smaller creature, it is pushed up to 20 feet straight away from the goristro and has the Prone condition.', 2),
  ('goristro', 'Slam', 'action'::rpg.actor_action_bucket, 13, '29', 'Melee Attack Roll: +13, reach 10 ft. Hit: 29 (4d10 + 7) Bludgeoning damage.', 3),
  ('goristro', 'Charge', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The goristro moves up to half its Speed straight toward an enemy it can see.', 4),
  ('grell', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The grell makes one Beak attack and one Paralyzing Tentacles attack.', 1),
  ('grell', 'Beak', 'action'::rpg.actor_action_bucket, 4, '11', 'Melee Attack Roll: +4, reach 5 ft. Hit: 11 (2d8 + 2) Piercing damage.', 2),
  ('grell', 'Paralyzing Tentacles', 'action'::rpg.actor_action_bucket, 4, '7', 'Melee Attack Roll: +4, reach 10 ft. Hit: 7 (1d10 + 2) Piercing damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 12) from two of ten tentacles. The target is also subjected to the following effect. Constitution Saving Throw: DC 11. Failure: The target has the Poisoned condition and repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically. While Poisoned, the target has the Paralyzed condition.', 3),
  ('grick', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The grick makes one Beak attack and one Tentacles attack.', 1),
  ('grick', 'Beak', 'action'::rpg.actor_action_bucket, 4, '9', 'Melee Attack Roll: +4, reach 5 ft. Hit: 9 (2d6 + 2) Piercing damage.', 2),
  ('grick', 'Tentacles', 'action'::rpg.actor_action_bucket, 4, '7', 'Melee Attack Roll: +4, reach 5 ft. Hit: 7 (1d10 + 2) Slashing damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 12) from all four tentacles.', 3),
  ('grick-anciano', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The grick makes one Beak attack, one Slam attack, and one Tentacles attack.', 1),
  ('grick-anciano', 'Beak', 'action'::rpg.actor_action_bucket, 7, '22', 'Melee Attack Roll: +7, reach 10 ft. Hit: 22 (4d8 + 4) Piercing damage.', 2),
  ('grick-anciano', 'Slam', 'action'::rpg.actor_action_bucket, NULL, '7', 'Melee Attack Roll: + 7, reach 10 ft. Hit: 7 (1d6 + 4) Bludgeoning damage. If the target is a Large or smaller creature, it has the Prone condition.', 3),
  ('grick-anciano', 'Tentacles', 'action'::rpg.actor_action_bucket, 7, '15', 'Melee Attack Roll: +7, reach 10 ft. Hit: 15 (2d10 + 4) Slashing damage. If the target is a Large or smaller creature, it has the Grappled condition (escape DC 14) from all four tentacles.', 4),
  ('grifo', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The griffon makes two Rend attacks.', 1),
  ('grifo', 'Rend', 'action'::rpg.actor_action_bucket, 6, '8', 'Melee Attack Roll: +6, reach 5 ft. Hit: 8 (1d8 + 4) Piercing damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 14) from both of the griffon’s front claws.', 2),
  ('grimlock', 'Bone Cudgel', 'action'::rpg.actor_action_bucket, 5, '6', 'Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Bludgeoning damage plus 2 (1d4) Psychic damage.', 1),
  ('guarda', 'Spear', 'action'::rpg.actor_action_bucket, 3, '4', 'Melee or Ranged Attack Roll: +3, reach 5 ft. or range 20/60 ft. Hit: 4 (1d6 + 1) Piercing damage.', 1),
  ('harpia', 'Claw', 'action'::rpg.actor_action_bucket, 3, '6', 'Melee Attack Roll: +3, reach 5 ft. Hit: 6 (2d4 + 1) Slashing damage.', 1),
  ('harpia', 'Luring Song', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The harpy sings a magical melody, which lasts until the harpy’s Concentration ends on it. Wisdom Saving Throw: DC 11, each Humanoid and Giant in a 300-foot Emanation originating from the harpy when the song starts. Failure: The target has the Charmed condition until the song ends and repeats the save at the end of each of its turns. While Charmed, the target has the Incapacitated condition and ignores the Luring Song of other harpies. If the target is more than 5 feet from the harpy, the target moves on its turn toward the harpy by the most direct route, trying to get within 5 feet of the harpy. It doesn’t avoid Opportunity Attacks; however, before moving into damaging terrain (such as lava or a pit) and whenever it takes damage from a source other than the harpy, the target repeats the save. Success: The target is immune to this harpy’s Luring Song for 24 hours.', 2),
  ('hezrou', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The hezrou makes three Rend attacks.', 1),
  ('hezrou', 'Rend', 'action'::rpg.actor_action_bucket, 7, '6', 'Melee Attack Roll: +7, reach 5 ft. Hit: 6 (1d4 + 4) Slashing damage plus 9 (2d8) Poison damage.', 2),
  ('hezrou', 'Leap', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The hezrou jumps up to 30 feet by spending 10 feet of movement.', 3),
  ('hidra', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The hydra makes as many Bite attacks as it has heads.', 1),
  ('hidra', 'Bite', 'action'::rpg.actor_action_bucket, 8, '10', 'Melee Attack Roll: +8, reach 10 ft. Hit: 10 (1d10 + 5) Piercing damage.', 2),
  ('hipogrifo', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The hippogriff makes two Rend attacks.', 1),
