  ('hobgoblin-capitao', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The hobgoblin makes two attacks, using Greatsword or Longbow in any combination.', 1),
  ('hobgoblin-capitao', 'Greatsword', 'action'::rpg.actor_action_bucket, 4, '9', 'Melee Attack Roll: +4, reach 5 ft. Hit: 9 (2d6 + 2) Slashing damage plus 3 (1d6) Poison damage.', 2),
  ('hobgoblin-capitao', 'Longbow', 'action'::rpg.actor_action_bucket, 4, '6', 'Ranged Attack Roll: +4, range 150/600 ft. Hit: 6 (1d8 + 2) Piercing damage plus 5 (2d4) Poison damage.', 3),
  ('hobgoblin-guerreiro', 'Longsword', 'action'::rpg.actor_action_bucket, 3, '12', 'Melee Attack Roll: +3, reach 5 ft. Hit: 12 (2d10 + 1) Slashing damage.', 1),
  ('hobgoblin-guerreiro', 'Longbow', 'action'::rpg.actor_action_bucket, 3, '5', 'Ranged Attack Roll: +3, range 150/600 ft. Hit: 5 (1d8 + 1) Piercing damage plus 7 (3d4) Poison damage.', 2),
  ('hobgoblin-senhor-da-guerra', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The hobgoblin makes three attacks, using Javelin or Longsword in any combination.', 1),
  ('hobgoblin-senhor-da-guerra', 'Javelin', 'action'::rpg.actor_action_bucket, 6, '11', 'Melee or Ranged Attack Roll: +6, reach 5 ft. or range 30/120 ft. Hit: 11 (2d6 + 4) Piercing damage, and the target’s Speed decreases by 10 feet until the start of the hobgoblin’s next turn.', 2),
  ('hobgoblin-senhor-da-guerra', 'Longsword', 'action'::rpg.actor_action_bucket, 6, '12', 'Melee Attack Roll: +6, reach 5 ft. Hit: 12 (2d8 + 3) Slashing damage.', 3),
  ('hobgoblin-senhor-da-guerra', 'Parry', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The hobgoblin is hit by a melee attack roll while holding a weapon: Response: The hobgoblin adds 3 to its AC against that attack, possibly causing it to miss.', 4),
  ('homem-lagarto-geomante', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The lizardfolk makes two Earth Burst attacks.', 1),
  ('homem-lagarto-geomante', 'Earth Burst', 'action'::rpg.actor_action_bucket, 4, '9', 'Melee or Ranged Attack Roll: +4, reach 5 ft. or range 60 ft. Hit: 9 (2d6 + 2) Bludgeoning damage.', 2),
  ('homem-lagarto-geomante', 'Hail of Stone (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 12, each creature in a 20-foot-radius, 40-foot-high Cylinder centered on a point the lizardfolk can see within 60 feet. Failure: 15 (6d4) Bludgeoning damage, and the target has the Prone condition. Success: Half damage only.', 3),
  ('homem-lagarto-geomante', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The lizardfolk casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 12):', 4),
  ('homem-lagarto-soberano', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The lizardfolk makes one Bite attack and one Earthen Maul attack.', 1),
  ('homem-lagarto-soberano', 'Bite', 'action'::rpg.actor_action_bucket, 5, '8', 'Melee Attack Roll: +5, reach 5 ft. Hit: 8 (1d10 + 3) Piercing damage. If the target is a creature that isn’t a Construct or an Undead, the lizardfolk gains Temporary Hit Points equal to the damage dealt.', 2),
  ('homem-lagarto-soberano', 'Earthen Maul', 'action'::rpg.actor_action_bucket, 5, '10', 'Melee Attack Roll: +5, reach 5 ft. Hit: 10 (2d6 + 3) Bludgeoning damage. If the target is a Medium or smaller creature, it has the Prone condition.', 3),
  ('homem-lagarto-soberano', 'Charge', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The lizardfolk moves up to its Speed or Swim Speed straight toward an enemy it can see.', 4),
  ('homunculo', 'Bite', 'action'::rpg.actor_action_bucket, 4, '1', 'Melee Attack Roll: +4, reach 5 ft. Hit: 1 Piercing damage, and the target is subjected to the following effect. Constitution Saving Throw: DC 12. Failure: The target has the Poisoned condition until the end of the homunculus’s next turn. Failure by 5 or More: The target has the Poisoned condition for 1 minute. While Poisoned, the target has the Unconscious condition, which ends early if the target takes any damage.', 1),
  ('horror-de-elmo', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The helmed horror makes two Arcane Sword attacks.', 1),
  ('horror-de-elmo', 'Arcane Sword', 'action'::rpg.actor_action_bucket, 6, '8', 'Melee Attack Roll: +6, reach 5 ft. Hit: 8 (1d8 + 4) Slashing damage plus 5 (1d10) Force damage.', 2),
  ('horror-de-gancho', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The hook horror makes two Hook attacks.', 1),
  ('horror-de-gancho', 'Hook', 'action'::rpg.actor_action_bucket, 6, '11', 'Melee Attack Roll: +6, reach 10 ft. Hit: 11 (2d6 + 4) Piercing damage. If the target is a Large or smaller creature, the hook horror moves the target 5 feet straight toward or away from itself.', 2),
  ('incubo', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The incubus makes two Restless Touch attacks.', 1),
  ('incubo', 'Restless Touch', 'action'::rpg.actor_action_bucket, 7, '15', 'Melee Attack Roll: +7, reach 5 ft. Hit: 15 (3d6 + 5) Psychic damage, and the target is cursed for 24 hours or until the incubus dies. Until the curse ends, the target gains no benefit from finishing Short Rests.', 2),
  ('incubo', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The incubus casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 15):', 3),
  ('incubo', 'Nightmare (Recharge 6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 15, one creature the incubus can see within 60 feet. Failure: If the target has 20 Hit Points or fewer, it has the Unconscious condition for 1 hour, until it takes damage, or until a creature within 5 feet of it takes an action to wake it. Otherwise, the target takes 18 (4d8) Psychic damage.', 4),
  ('kenku', 'Shadow Blade', 'action'::rpg.actor_action_bucket, 5, '6', 'Melee or Ranged Attack Roll: +5, reach 5 ft. or range 60 ft. Hit: 6 (1d6 + 3) Necrotic damage. Hit or Miss: The blade magically returns to the kenku’s hand immediately after a ranged attack.', 1),
  ('kenku', 'Eldritch Lantern (Recharge 4–6)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The kenku casts Faerie Fire, using Intelligence as the spellcasting ability (spell save DC 10).', 2),
  ('kobold-alado', 'Dragon-Tooth Blade', 'action'::rpg.actor_action_bucket, 5, '6', 'Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Piercing damage.', 1),
  ('kobold-alado', 'Chromatic Spittle', 'action'::rpg.actor_action_bucket, 5, '6', 'Ranged Attack Roll: +5, range 30 ft. Hit: 6 (1d6 + 3) damage of a type chosen by the kobold: Acid, Cold, Fire, Lightning, or Poison.', 2),
  ('kobold-guerreiro', 'Dagger', 'action'::rpg.actor_action_bucket, 4, '4', 'Melee or Ranged Attack Roll: +4, reach 5 ft. or range 20/60 ft. Hit: 4 (1d4 + 2) Piercing damage.', 1),
  ('kraken', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The kraken makes two Tentacle attacks and uses Fling, Lightning Strike, or Swallow.', 1),
  ('kraken', 'Tentacle', 'action'::rpg.actor_action_bucket, 17, '24', 'Melee Attack Roll: +17, reach 30 ft. Hit: 24 (4d6 + 10) Bludgeoning damage. The target has the Grappled condition (escape DC 20) from one of ten tentacles, and it has the Restrained condition until the grapple ends.', 2),
  ('kraken', 'Fling', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The kraken throws a Large or smaller creature Grappled by it to a space it can see within 60 feet of itself that isn’t in the air. Dexterity Saving Throw: DC 25, the creature thrown and each creature in the destination space. Failure: 18 (4d8) Bludgeoning damage, and the target has the Prone condition. Success: Half damage only.', 3),
  ('kraken', 'Lightning Strike', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 23, one creature the kraken can see within 120 feet. Failure: 33 (6d10) Lightning damage. Success: Half damage.', 4),
  ('kraken', 'Swallow', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 25, one creature Grappled by the kraken (it can have up to four creatures swallowed at a time). Failure: 23 (3d8 + 10) Piercing damage. If the target is Large or smaller, it is swallowed and no longer Grappled. A swallowed creature has the Restrained condition, has Total Cover against attacks and other effects outside the kraken, and takes 24 (7d6) Acid damage at the start of each of its turns.', 5),
  ('kraken', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature’s turn, the kraken can expend a use to take one of the following actions. The kraken regains all expended uses at the start of each of its turns.', 6),
  ('kraken', 'Storm Bolt', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The kraken uses Lightning Strike.', 7),
  ('kraken', 'Toxic Ink', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 23, each creature in a 15-foot Emanation originating from the kraken while it is underwater. Failure: The target has the Blinded and Poisoned conditions until the end of the kraken’s next turn. The kraken then moves up to its Speed. Failure or Success: The kraken can’t take this action again until the start of its next turn.', 8),
  ('kuo-toa', 'Spear', 'action'::rpg.actor_action_bucket, 3, '5', 'Melee or Ranged Attack Roll: +3, reach 5 ft. or range 20/60 ft. Hit: 5 (1d8 + 1) Piercing damage.', 1),
  ('kuo-toa', 'Sticky Net (1/Day)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 10, one Large or smaller creature the kuo-toa can see within 15 feet. Failure: The target has the Restrained condition until the net is destroyed (AC 10; HP 5; Immunity to Bludgeoning, Poison, and Psychic damage). A creature can take an action to make a DC 10 Strength (Athletics) check to free itself or another creature in a net within 5 feet, destroying the net on a success.', 2),
  ('kuo-toa', 'Sticky Shield', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: A creature misses the kuo-toa with a melee attack roll using a weapon. Response—Strength Saving Throw: DC 11, the triggering creature. Failure: The attack’s weapon sticks to the kuo-toa’s shield. If the target doesn’t let go of the weapon, the target has the Grappled condition while the weapon is stuck (escape DC 11). While stuck, the weapon can’t be used. The target can take an action to make a DC 11 Strength (Athletics) check, freeing the weapon on a success.', 3),
  ('kuo-toa-arquipreste', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The kuo-toa makes three Strange Scepter attacks.', 1),
  ('kuo-toa-arquipreste', 'Strange Scepter', 'action'::rpg.actor_action_bucket, 6, '20', 'Melee or Ranged Attack Roll: +6, reach 5 ft. or range 120 ft. Hit: 20 (5d6 + 3) Lightning damage.', 2),
  ('kuo-toa-arquipreste', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The kuo-toa casts one of the following spells, requiring no Material components and using Wisdom as the spellcasting ability (spell save DC 14):', 3),
  ('kuo-toa-arquipreste', 'Shield of Faith (2/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The kuo-toa casts Shield of Faith, using the same spellcasting ability as Spellcasting.', 4),
  ('kuo-toa-chicote', 'Pincer Staff', 'action'::rpg.actor_action_bucket, 4, '9', 'Melee Attack Roll: +4, reach 10 ft. Hit: 9 (2d6 + 2) Piercing damage. If the target is a Medium or smaller creature, it has the Grappled condition (escape DC 12). Until the grapple ends, the kuo-toa can’t make Pincer Staff attacks.', 1),
  ('kuo-toa-chicote', 'Conjure Slimy Glob', 'action'::rpg.actor_action_bucket, 4, '9', 'Ranged Attack Roll: +4, range 60 ft. Hit: 9 (3d4 + 2) Acid damage.', 2),
  ('kuo-toa-chicote', 'Shield of Faith (2/Day)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The kuo-toa casts Shield of Faith, using Wisdom as the spellcasting ability.', 3),
  ('kuo-toa-monitor', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The kuo-toa makes two Bone Whip attacks.', 1),
  ('kuo-toa-monitor', 'Bone Whip', 'action'::rpg.actor_action_bucket, 5, '6', 'Melee Attack Roll: +5, reach 10 ft. Hit: 6 (1d6 + 3) Slashing damage plus 7 (2d6) Lightning damage, and the target can’t make Opportunity Attacks until the start of the kuo-toa’s next turn.', 2),
  ('lamia', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The lamia makes two Claw attacks. It can replace one attack with a use of Corrupting Touch.', 1),
  ('lamia', 'Claw', 'action'::rpg.actor_action_bucket, 5, '7', 'Melee Attack Roll: +5, reach 5 ft. Hit: 7 (1d8 + 3) Slashing damage plus 7 (2d6) Psychic damage.', 2),
  ('lamia', 'Corrupting Touch', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 13, one creature the lamia can see within 5 feet. Failure: 13 (3d8) Psychic damage, and the target is cursed for 1 hour. Until the curse ends, the target has the Charmed and Poisoned conditions.', 3),
  ('lamia', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The lamia casts one of the following spells, requiring no Material components and using Charisma as the spellcasting ability (spell save DC 13):', 4),
  ('lamia', 'Leap', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The lamia jumps up to 30 feet by spending 10 feet of movement.', 5),
  ('larva', 'Bite', 'action'::rpg.actor_action_bucket, 1, '1', 'Melee Attack Roll: +1, reach 5 ft. Hit: 1 (1d4 - 1) Necrotic damage.', 1),
  ('lemure', 'Vile Slime', 'action'::rpg.actor_action_bucket, 2, '2', 'Melee Attack Roll: +2, reach 5 ft. Hit: 2 (1d4) Poison damage.', 1),
  ('lich', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The lich makes three attacks, using Eldritch Burst or Paralyzing Touch in any combination.', 1),
  ('lich', 'Eldritch Burst', 'action'::rpg.actor_action_bucket, 12, '31', 'Melee or Ranged Attack Roll: +12, reach 5 ft. or range 120 ft. Hit: 31 (4d12 + 5) Force damage.', 2),
  ('lich', 'Paralyzing Touch', 'action'::rpg.actor_action_bucket, 12, '15', 'Melee Attack Roll: +12, reach 5 ft. Hit: 15 (3d6 + 5) Cold damage, and the target has the Paralyzed condition until the start of the lich’s next turn.', 3),
  ('lich', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The lich casts one of the following spells, using Intelligence as the spellcasting ability (spell save DC 20):', 4),
  ('lich', 'Protective Magic', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'The lich casts Counterspell or Shield in response to the spell’s trigger, using the same spellcasting ability as Spellcasting.', 5),
  ('lich', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature’s turn, the lich can expend a use to take one of the following actions. The lich regains all expended uses at the start of each of its turns.', 6),
  ('lich', 'Deathly Teleport', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The lich teleports up to 60 feet to an unoccupied space it can see, and each creature within 10 feet of the space it left takes 11 (2d10) Necrotic damage.', 7),
  ('lich', 'Disrupt Life', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 20, each creature that isn’t an Undead in a 20-foot Emanation originating from the lich. Failure: 31 (9d6) Necrotic damage. Success: Half damage. Failure or Success: The lich can’t take this action again until the start of its next turn.', 8),
  ('lich', 'Frightening Gaze', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The lich casts Fear, using the same spellcasting ability as Spellcasting. The lich can’t take this action again until the start of its next turn.', 9),
  ('lodo-cinzento', 'Pseudopod', 'action'::rpg.actor_action_bucket, 3, '10', 'Melee Attack Roll: +3, reach 5 ft. Hit: 10 (2d8 + 1) Acid damage. Nonmagical armor worn by the target takes a -1 penalty to the AC it offers. The armor is destroyed if the penalty reduces its AC to 10. The penalty can be removed by casting the Mending spell on the armor.', 1),
  ('lodo-cinzento-psiquico', 'Pseudopod', 'action'::rpg.actor_action_bucket, 3, '11', 'Melee Attack Roll: +3, reach 5 ft. Hit: 11 (3d6 + 1) Acid damage, and the target has Disadvantage on Intelligence saving throws until the end of the ooze’s next turn.', 1),
  ('lodo-cinzento-psiquico', 'Psychic Crush', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Intelligence Saving Throw: DC 10, one creature the ooze can see within 60 feet. Failure: 13 (3d8) Psychic damage.', 2),
  ('lodo-cinzento-psiquico', 'Mind Corrosion', 'reaction'::rpg.actor_action_bucket, NULL, NULL, 'Trigger: The ooze fails a saving throw against a spell or another magical effect created by a creature. Response: The triggering creature takes 3 (1d6) Psychic damage.', 3),
  ('manto', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The cloaker makes one Attach attack and two Tail attacks.', 1),
  ('manto', 'Attach', 'action'::rpg.actor_action_bucket, 6, '13', 'Melee Attack Roll: +6, reach 5 ft. Hit: 13 (3d6 + 3) Piercing damage. If the target is a Large or smaller creature, the cloaker attaches to it. While the cloaker is attached, the target has the Blinded condition, and the cloaker can’t make Attach attacks against other targets. In addition, the cloaker halves the damage it takes (round down), and the target takes the same amount of damage.', 2),
  ('manto', 'Tail', 'action'::rpg.actor_action_bucket, 6, '8', 'Melee Attack Roll: +6, reach 10 ft. Hit: 8 (1d10 + 3) Slashing damage.', 3),
  ('manto', 'Moan', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'Wisdom Saving Throw: DC 13, each creature in a 60-foot Emanation originating from the cloaker. Failure: The target has the Frightened condition until the end of the cloaker’s next turn. Success: The target is immune to this cloaker’s Moan for the next 24 hours.', 4),
  ('manto', 'Phantasms (Recharge after a Short or Long Rest)', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The cloaker casts the Mirror Image spell, requiring no spell components and using Wisdom as the spellcasting ability. The spell ends early if the cloaker starts or ends its turn in Bright Light.', 5),
  ('manto-sombrio', 'Crush', 'action'::rpg.actor_action_bucket, 5, '6', 'Melee Attack Roll: +5, reach 5 ft. Hit: 6 (1d6 + 3) Bludgeoning damage, and the darkmantle attaches to the target. If the target is a Medium or smaller creature and the darkmantle had Advantage on the attack roll, it covers the target, which has the Blinded condition and is suffocating while the darkmantle is attached in this way.', 1),
  ('manto-sombrio', 'Darkness Aura (1/Day)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Magical Darkness fills a 15-foot Emanation originating from the darkmantle. This effect lasts while the darkmantle maintains Concentration on it, up to 10 minutes. Darkvision can’t penetrate this area, and no light can illuminate it.', 2),
  ('meio-dragao', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The half-dragon makes two Claw attacks.', 1),
  ('meio-dragao', 'Claw', 'action'::rpg.actor_action_bucket, 7, '6', 'Melee Attack Roll: +7, reach 10 ft. Hit: 6 (1d4 + 4) Slashing damage plus 7 (2d6) damage of the type chosen for the Draconic Origin trait.', 2),
  ('meio-dragao', 'Dragon’s Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 14, each creature in a 30-foot Cone. Failure: 28 (8d6) damage of the type chosen for the Draconic Origin trait. Success: Half damage.', 3),
  ('meio-dragao', 'Leap', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The half-dragon jumps up to 30 feet by spending 10 feet of movement.', 4),
  ('naga-guardia', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The naga makes two Bite attacks. It can replace any attack with a use of Poisonous Spittle.', 1),
  ('naga-guardia', 'Bite', 'action'::rpg.actor_action_bucket, 8, '17', 'Melee Attack Roll: +8, reach 10 ft. Hit: 17 (2d12 + 4) Piercing damage plus 22 (4d10) Poison damage.', 2),
  ('naga-guardia', 'Poisonous Spittle', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 16, one creature the naga can see within 60 feet. Failure: 31 (7d8) Poison damage, and the target has the Blinded condition until the start of the naga’s next turn. Success: Half damage only.', 3),
  ('naga-guardia', 'Spellcasting', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The naga casts one of the following spells, requiring no Somatic or Material components and using Wisdom as the spellcasting ability (spell save DC 16):', 4),
  ('perseguidor-invisivel', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The stalker makes three Wind Swipe attacks. It can replace one attack with a use of Vortex.', 1),
  ('perseguidor-invisivel', 'Wind Swipe', 'action'::rpg.actor_action_bucket, 7, '11', 'Melee Attack Roll: +7, reach 5 ft. Hit: 11 (2d6 + 4) Force damage.', 2),
  ('perseguidor-invisivel', 'Vortex', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 14, one Large or smaller creature in the stalker’s space. Failure: 7 (1d8 + 3) Thunder damage, and the target has the Grappled condition (escape DC 13). Until the grapple ends, the target can’t cast spells with a Verbal component and takes 7 (2d6) Thunder damage at the start of each of the stalker’s turns.', 3),
  ('plebeu', 'Club', 'action'::rpg.actor_action_bucket, 2, '2', 'Melee Attack Roll: +2, reach 5 ft. Hit: 2 (1d4) Bludgeoning damage.', 1),
  ('quimera', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The chimera makes one Ram attack, one Bite attack, and one Claw attack. It can replace the Claw attack with a use of Fire Breath if available.', 1),
  ('quimera', 'Bite', 'action'::rpg.actor_action_bucket, 7, '11', 'Melee Attack Roll: +7, reach 5 ft. Hit: 11 (2d6 + 4) Piercing damage, or 18 (4d6 + 4) Piercing damage if the chimera had Advantage on the attack roll.', 2),
  ('quimera', 'Claw', 'action'::rpg.actor_action_bucket, 7, '7', 'Melee Attack Roll: +7, reach 5 ft. Hit: 7 (1d6 + 4) Slashing damage.', 3),
  ('quimera', 'Ram', 'action'::rpg.actor_action_bucket, 7, '10', 'Melee Attack Roll: +7, reach 5 ft. Hit: 10 (1d12 + 4) Bludgeoning damage. If the target is a Medium or smaller creature, it has the Prone condition.', 4),
  ('quimera', 'Fire Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Dexterity Saving Throw: DC 15, each creature in a 15-foot Cone. Failure: 31 (7d8) Fire damage. Success: Half damage.', 5),
  ('rastejante-carniceiro', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The carrion crawler uses Paralyzing Tentacles and makes one Bite attack.', 1),
  ('rastejante-carniceiro', 'Bite', 'action'::rpg.actor_action_bucket, 4, '7', 'Melee Attack Roll: +4, reach 5 ft. Hit: 7 (2d4 + 2) Piercing damage plus 3 (1d6) Poison damage.', 2),
  ('rastejante-carniceiro', 'Paralyzing Tentacles', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 12, one creature the carrion crawler can see within 10 feet. Failure: The target has the Poisoned condition and repeats the save at the end of each of its turns, ending the effect on itself on a success. After 1 minute, it succeeds automatically. While Poisoned, the target has the Paralyzed condition.', 3),
  ('semilich', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The demilich makes three Necrotic Burst attacks.', 1),
  ('semilich', 'Necrotic Burst', 'action'::rpg.actor_action_bucket, 11, '24', 'Melee or Ranged Attack Roll: +11, reach 5 ft. or range 120 ft. Hit: 24 (7d6) Necrotic damage.', 2),
  ('semilich', 'Howl (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 19, each creature in a 30-foot Emanation originating from the demilich. Failure: 70 (20d6) Psychic damage. Failure or Success: The target has the Frightened condition until the start of the demilich’s next turn.', 3),
  ('semilich', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature’s turn, the demilich can expend a use to take one of the following actions. The demilich regains all expended uses at the start of each of its turns.', 4),
  ('semilich', 'Energy Drain', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 19, one creature the demilich can see within 120 feet. Failure: The target’s Hit Point maximum decreases by 14 (4d6). Failure or Success: The demilich can’t take this action again until the start of its next turn.', 5),
  ('semilich', 'Grave-Dust Flight', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The demilich flies up to its Fly Speed, shedding grave dust. Each creature within 5 feet of the demilich as it moves is targeted once by the following effect. Constitution Saving Throw: DC 19. Failure: The target has the Blinded condition until the end of the demilich’s next turn. Failure or Success: The demilich can’t take this action again until the start of its next turn.', 6),
  ('semilich', 'Necrosis', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The demilich makes one Necrotic Burst attack.', 7),
  ('tartaruga-dragao', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The dragon makes three Bite attacks. It can replace one attack with a Tail attack.', 1),
  ('tartaruga-dragao', 'Bite', 'action'::rpg.actor_action_bucket, 13, '23', 'Melee Attack Roll: +13, reach 15 ft. Hit: 23 (3d10 + 7) Piercing damage plus 7 (2d6) Fire damage. Being underwater doesn’t grant Resistance to this Fire damage.', 2),
  ('tartaruga-dragao', 'Tail', 'action'::rpg.actor_action_bucket, 13, '18', 'Melee Attack Roll: +13, reach 15 ft. Hit: 18 (2d10 + 7) Bludgeoning damage. If the target is a Huge or smaller creature, it has the Prone condition.', 3),
  ('tartaruga-dragao', 'Steam Breath (Recharge 5–6)', 'action'::rpg.actor_action_bucket, NULL, NULL, 'Constitution Saving Throw: DC 19, each creature in a 60-foot Cone. Failure: 56 (16d6) Fire damage. Success: Half damage. Failure or Success: Being underwater doesn’t grant Resistance to this Fire damage.', 4),
  ('tirano-da-morte', 'Multiattack', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The death tyrant uses Eye Rays three times.', 1),
  ('tirano-da-morte', 'Bite', 'action'::rpg.actor_action_bucket, 9, '13', 'Melee Attack Roll: +9, reach 5 feet. Hit: 13 (2d8 + 4) Piercing damage.', 2),
  ('tirano-da-morte', 'Eye Rays', 'action'::rpg.actor_action_bucket, NULL, NULL, 'The death tyrant randomly shoots one of the following magical rays at a target it can see within 120 feet of itself (roll 1d10; reroll if the death tyrant has already used that ray during this turn):', 3),
  ('tirano-da-morte', 'Negative Energy Cone', 'bonus'::rpg.actor_action_bucket, NULL, NULL, 'The death tyrant’s central eye emits an imperceptible, magical wave of negative energy in a 150-foot Cone. Creatures in that area can’t regain Hit Points until the start of the death tyrant’s next turn. An intact Humanoid corpse there instantly rises as a Zombie under the death tyrant’s control and takes its turn immediately after the death tyrant on the same Initiative count.', 4),
  ('tirano-da-morte', 'Legendary Action Uses', 'legendary'::rpg.actor_action_bucket, NULL, NULL, '3 (4 in Lair). Immediately after another creature’s turn, the death tyrant can expend a use to take one of the following actions. The death tyrant regains all expended uses at the start of each of its turns.', 5),
  ('tirano-da-morte', 'Chomp', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The death tyrant makes two Bite attacks.', 6),
  ('tirano-da-morte', 'Glare', 'legendary'::rpg.actor_action_bucket, NULL, NULL, 'The death tyrant uses Eye Rays.', 7);

